  "Este mapa todavía no tiene imagen.": "이 지도에는 아직 이미지가 없습니다.",
  "¿Eliminar este mapa?": "이 지도를 삭제하시겠습니까?",
  "Se borran su imagen, sus capas y sus chinchetas. Los mapas que cuelgan de él NO se borran: quedan sueltos. Los lugares tampoco se tocan.": "해당 이미지, 레이어 및 핀이 삭제됩니다. 거기에 매달려 있는 지도는 느슨하게 남아 있습니다. 장소는 그대로 유지됩니다.",
  "Todavía no hay mapas en este mundo. Crea uno y sube tu propia imagen, o genérala con IA; después podrás calibrar su escala y clavar en él los lugares que ya has guardado.": "이 세상에는 아직 지도가 없습니다. 하나를 만들고 자신만의 이미지를 업로드하거나 AI로 생성하세요. 그런 다음 규모를 보정하고 이미 저장한 장소에 고정할 수 있습니다.",
  "Un mapa puede ser el mapa de un lugar concreto. No hace falta: un mapa de rutas cruza cinco reinos y no es de ninguno.": "지도는 특정 장소의 지도일 수 있습니다. 그럴 필요는 없습니다. 무역로 지도는 다섯 왕국을 가로지르며 어느 왕국에도 속하지 않습니다.",
  "Al crearlo podrás subir tu propia imagen. Después se calibra la escala y se clavan encima los lugares que ya tengas guardados.": "일단 생성되면 자신의 이미지를 업로드할 수 있습니다. 그런 다음 저울을 보정하고 이미 있는 위치에 고정합니다.",
  "Mundo": "세계",
  "Interior": "내부",
  "Mazmorra": "지하 감옥",
  "Traduce texto, documentos y adjuntos de Zotero con el modelo que elijas, incluido un modo PDF facsímil.": "PDF 팩시밀리 모드를 포함하여 텍스트, 문서 및 Zotero 첨부 파일을 선택한 모델로 번역하세요.",
  "Traducir texto, documentos y adjuntos de Zotero con el modelo elegido, conservando la estructura de DOCX y EPUB y la apariencia de los PDF mediante un modo facsímil.": "팩시밀리 모드를 통해 DOCX 및 EPUB 구조와 PDF 모양을 유지하면서 선택한 모델로 텍스트, 문서 및 Zotero 첨부 파일을 번역합니다.",
  "Mover documento a la papelera": "문서를 휴지통으로 이동",
  "Mover documentos a la papelera": "문서를 휴지통으로 이동",
  "«{name}» dejará de aparecer. Podrás recuperarlo desde la administración de datos.": "“{name}”은 더 이상 표시되지 않습니다. 데이터 관리에서 복구할 수 있습니다.",
  "Los {n} documentos seleccionados dejarán de aparecer. Podrás recuperarlos desde la administración de datos.": "{n} 선택한 문서가 더 이상 표시되지 않습니다. 데이터 관리에서 복구할 수 있습니다.",
  "¿Eliminar también las ideas vinculadas?": "연결된 아이디어도 삭제하시겠습니까?",
  "Se eliminarán las ideas que solo proceden de estos documentos, junto con sus embeddings, evidencia y conexiones. Las ideas compartidas con otras fuentes se conservarán.": "이러한 문서에서만 나온 아이디어는 포함, 증거 및 연결과 함께 삭제됩니다. 다른 소스와 공유된 아이디어는 유지됩니다.",
  "Eliminar ideas y embeddings": "아이디어 및 임베딩 삭제",
