  "Eliminar idea": "아이디어 삭제",
  "Se eliminará «{name}» junto con su embedding, evidencia y conexiones. Esta acción no se puede deshacer.": "“{name}”은 포함, 증거 및 연결과 함께 삭제됩니다. 이 작업은 취소할 수 없습니다.",
