  "No se puede cambiar de bóveda con la cola de análisis activa. Pausa o termina los trabajos pendientes antes de cargar otra bóveda.": "분석 대기열이 활성화되어 있는 동안에는 저장소를 전환할 수 없습니다. 다른 Vault를 로드하기 전에 대기 중인 작업을 일시 중지하거나 완료하세요.",
  "No se puede cambiar de bóveda mientras se están indexando embeddings de ideas.": "아이디어 임베딩이 색인화되는 동안에는 저장소를 전환할 수 없습니다.",
