  "Se ocultarán de la cola las tareas completadas, canceladas o fallidas. Se conservarán las tareas en curso, pendientes o en pausa y los documentos generados.": "완료, 취소 또는 실패한 작업은 대기열에서 숨겨집니다. 실행 중이거나 보류 중이거나 일시 중지된 작업과 생성된 문서는 보관됩니다.",
