  "Este criterio junta dos aspectos: sepáralos para poder evaluarlos por separado.": "이 기준은 두 가지 측면을 묶은 것입니다. 즉, 각각을 별도로 판단할 수 있도록 분할하는 것입니다.",
  "Este descriptor solo emite un juicio: describe qué hace el trabajo.": "이 설명자는 판단만 전달합니다. 작업이 실제로 수행하는 작업을 설명합니다.",
  "Este descriptor describe carencias: redáctalo en positivo, por lo que el trabajo sí hace.": "이 설명자는 누락된 내용을 설명합니다. 즉, 작업이 수행하는 작업을 중심으로 다시 작성합니다.",
