  "Llevar Nodus a iPhone y iPad con aplicaciones nativas adaptadas a cada dispositivo.": "각 기기에 맞는 기본 앱을 사용하여 Nodus를 iPhone 및 iPad로 가져오세요.",
  "Otros vaults sugeridos por usuarios": "기타 사용자 제안 Vault",
  "Vaults sugeridos por usuarios": "사용자 제안 Vault",
