  "El puente de Nodus (preload) no está disponible. La app no puede comunicarse con su backend.": "Nodus 브리지(예압)를 사용할 수 없습니다. 앱이 백엔드와 통신할 수 없습니다.",
  "No se pudieron cargar los ajustes: {msg}": "설정을 로드할 수 없습니다: {msg}",
