  "Cargar claves": "키 로드",
  "Reutilizar análisis de otras bóvedas": "다른 Vault의 분석 재사용",
  "Busca coincidencias en otras bóvedas y, si encuentra ideas, embeddings, resúmenes o pasajes ya generados, los importa antes de usar IA.": "다른 Vault에서 일치하는 항목을 찾아 이미 생성된 아이디어, 임베딩, 요약 또는 구절을 찾으면 AI를 사용하기 전에 이를 가져옵니다.",
  "Análisis reutilizado desde otras bóvedas para {n} obra(s).": "{n} 작업에 대해 다른 저장소의 분석을 재사용했습니다.",
  "{n} documento(s) añadidos; {reused} componente(s) reutilizados con huellas exactas.": "{n}개의 문서가 추가되었습니다. {reused}개의 구성 요소가 정확한 지문으로 재사용되었습니다.",
  "No se encontró análisis reutilizable en otras bóvedas para la selección.": "선택 항목에 대해 다른 저장소에서 재사용 가능한 분석을 찾을 수 없습니다.",
  "Zona peligrosa": "위험지대",
  "Vault objetivo": "대상 Vault",
  "Reinicializar": "다시 놓기",
  "La bóveda activa no se puede eliminar. Carga otra bóveda antes.": "활성 Vault는 삭제할 수 없습니다. 먼저 다른 Vault를 로드하세요.",
  "La bóveda principal no se puede eliminar; puedes reinicializarla.": "기본 Vault는 삭제할 수 없습니다. 대신 재설정할 수 있습니다.",
  "Eliminar bóveda": "Vault 삭제",
  "Reinicializar bóveda": "Vault 재설정",
  "Esta acción eliminará la bóveda \"{name}\" y sus archivos locales. No afecta a otras bóvedas.": "그러면 \"{name}\" Vault와 해당 로컬 파일이 삭제됩니다. 다른 저장소에는 영향을 주지 않습니다.",
  "Esta acción borrará el contenido de \"{name}\" y recreará su base de datos vacía. No afecta a otras bóvedas.": "이렇게 하면 \"{name}\"의 내용이 지워지고 빈 데이터베이스가 다시 생성됩니다. 다른 저장소에는 영향을 주지 않습니다.",
  "Continuar": "계속하다",
  "Introduce este código manualmente": "이 코드를 직접 입력하세요",
  "Introduce este código manualmente para eliminar la bóveda \"{name}\".": "\"{name}\" Vault를 삭제하려면 이 코드를 수동으로 입력하세요.",
  "Código de seguridad": "보안 코드",
  "No se puede pegar aquí. Escribe las cuatro cifras manualmente.": "여기에는 붙여넣을 수 없습니다. 4자리 숫자를 수동으로 입력하세요.",
  "Código incorrecto.": "코드가 잘못되었습니다.",
  "Escribe las cuatro cifras para continuar.": "계속하려면 4자리 숫자를 입력하세요.",
  "Código correcto. Confirma una última vez para ejecutar la acción.": "코드가 승인되었습니다. 작업을 실행하려면 마지막으로 한 번 더 확인하세요.",
  "Código correcto. Confirma una última vez para eliminar la bóveda \"{name}\".": "코드가 승인되었습니다. \"{name}\" Vault를 삭제하려면 마지막으로 한 번 더 확인하세요.",
  "Eliminar definitivamente": "영구 삭제",
  "Reinicializar definitivamente": "영구적으로 재설정",
  "Bóveda eliminada.": "Vault가 삭제되었습니다.",
  "Bóveda reinicializada.": "Vault 재설정.",
  "Escribe un nombre para la bóveda.": "Vault 이름을 입력하세요.",
  "Bóveda renombrada.": "Vault의 이름이 변경되었습니다.",
  "Bóveda duplicada.": "Vault가 중복되었습니다.",
  "Testimonios": "증언",
  "Prosopografía": "프로소포그래피",
  "Worldbuilding": "세계관 구축",
  "Docencia": "교육",
  "Investigación, análisis y escritura.": "연구, 분석, 글쓰기.",
  "Historia familiar y archivos.": "가족 역사 및 기록 보관소.",
  "Aprendizaje y materiales de estudio.": "학습 및 학습 자료.",
  "Tablas, datos y análisis.": "테이블, 데이터 및 분석.",
  "Archivos y fuentes históricas.": "기록 보관소 및 역사적 출처.",
  "Entrevistas, historia oral y periodismo.": "인터뷰, 구술 역사, 저널리즘.",
  "Mundos, personajes y narrativas.": "세계, 캐릭터, 내러티브.",
  "Cursos, evaluación y materiales.": "강좌, 평가, 자료.",
  "Creación de mundos para escritores.": "작가를 위한 세계관 구축.",
  "Clases, cursos y materiales; la IA solo verá placeholders del alumnado.": "수업, 강좌 및 자료 AI는 학생 자리 표시자만 볼 수 있습니다.",
  "Vista previa navegable. Puedes crear el vault y consultar sus secciones, pero todavía no contienen funciones.": "탐색 가능한 미리보기. Vault를 생성하고 해당 섹션을 찾아볼 수 있지만 아직 기능이 포함되어 있지 않습니다.",
  "Este vault es una preview navegable: se creará normalmente, pero por ahora sus secciones son solo una muestra y no permiten realizar acciones.": "이 Vault는 탐색 가능한 미리보기입니다. 정상적으로 생성되지만 현재 해당 섹션은 쇼케이스일 뿐이며 어떤 작업도 허용되지 않습니다.",
  "Este vault muestra la estructura prevista. Sus secciones todavía no permiten realizar acciones.": "이 Vault는 계획된 구조를 보여줍니다. 해당 섹션에서는 아직 어떤 작업도 허용하지 않습니다.",
  "Disponible próximamente": "곧 이용 가능",
