  "El idioma de los prompts determina en qué idioma la IA genera ideas, temas, narrativa del tutor y borradores. Las citas textuales siempre conservan el idioma original de la fuente.": "프롬프트 언어는 AI가 아이디어, 테마, 교사 내러티브 및 초안을 생성하는 데 사용하는 언어를 결정합니다. 축어적 인용문은 항상 원본 언어를 유지합니다.",
