  "El motor, el modelo y sus descargas se gestionan aquí. Los motores locales trabajan fuera del hilo de la interfaz y no envían el audio a terceros.": "여기에서 엔진, 모델, 다운로드를 관리하세요. 로컬 엔진은 UI 스레드에서 실행되며 오디오를 제3자에게 보내지 않습니다.",
