  "El vocabulario del apunte y el diccionario personal se usan como contexto. Los audios se guardan solo en este dispositivo y se excluyen de sync y backups.": "노트 어휘와 개인 사전이 문맥으로 사용됩니다. 오디오는 이 기기에 유지되며 동기화 및 백업에서 제외됩니다.",
