  "Paletas de color. El modo claro u oscuro se ajusta aparte.": "색상 팔레트. 밝거나 어두운 모드는 별도로 설정됩니다.",
  "Paletas de color. El modo claro u oscuro se ajusta arriba.": "색상 팔레트. 밝거나 어두운 모드는 위에서 설정됩니다.",
  "Usar la misma paleta en todas las bóvedas": "모든 Vault에서 동일한 팔레트 사용",
  "Activado, todas las bóvedas comparten la paleta. Desactivado, cada una recuerda la suya y las nuevas empiezan con la predeterminada. El modo claro u oscuro es común en ambos casos.": "켜면 모든 Vault가 팔레트를 공유합니다. 끄면 각 저장소가 자체 저장소를 유지하고 새 저장소가 기본 저장소에서 시작됩니다. 밝거나 어두운 모드는 어느 쪽이든 공유됩니다.",
