  "El flujo completo: leer con criterio, comprender el corpus, encontrar tu aportación y escribir.": "전체 흐름: 비판적으로 읽고, 말뭉치를 이해하고, 기여한 바를 찾고, 글을 쓰세요.",
  "Empezar": "시작",
