  "sin respuesta": "응답 없음",
  "Comprueba que Zotero esté abierto y que «Permitir que otras aplicaciones de este ordenador se comuniquen con Zotero» esté activado en los ajustes Avanzados de Zotero.": "Zotero가 열려 있는지 확인하고 Zotero의 고급 설정에서 \"이 컴퓨터의 다른 응용 프로그램이 Zotero와 통신하도록 허용\"이 활성화되어 있는지 확인하세요.",
  "Elige las colecciones a monitorizar. Se incorporan metadatos; los análisis se lanzan manualmente salvo que actives automatización en Ajustes.": "모니터링할 컬렉션을 선택합니다. 메타데이터가 수집됩니다. 설정에서 자동화를 활성화하지 않으면 분석이 수동으로 실행됩니다.",
  "ítems": "아이템",
