  "⚠ Sin un modelo seleccionado podrás sincronizar metadatos, pero no analizar temas ni ideas hasta configurarlo.": "⚠ 선택한 모델이 없으면 메타데이터를 동기화할 수 있지만 구성할 때까지는 테마나 아이디어를 분석할 수 없습니다.",
  "Sincronizando Zotero para preparar el panel inicial...": "초기 대시보드를 준비하기 위해 Zotero를 동기화하는 중...",
  "No se pudo completar la primera sincronización, pero puedes entrar y corregirlo desde Inicio o Ajustes.": "첫 번째 동기화를 완료하지 못했는데, 홈이나 설정에서 입력하고 수정할 수 있습니다.",
