  "La sincronización puede funcionar, pero Nodus necesita un modelo predeterminado para extraer temas, ideas y evidencias.": "동기화는 작동할 수 있지만 Nodus는 테마, 아이디어 및 증거를 추출하기 위해 기본 모델이 필요합니다.",
  "Sincroniza Zotero para crear el corpus": "Zotero를 동기화하여 코퍼스 생성",
  "Todavía no hay obras locales. Revisa las colecciones monitorizadas y ejecuta una sincronización para poblar la biblioteca.": "아직 국내 작품이 없습니다. 모니터링되는 컬렉션을 검토하고 동기화를 실행하여 라이브러리를 채웁니다.",
  "Sincronizar ahora": "지금 동기화",
  "Completa el análisis ligero": "빛 분석 완료",
  "El primer resultado visible del mapa depende de los temas extraídos a partir de título y resumen. Analiza temas antes de profundizar.": "지도에 표시되는 첫 번째 결과는 제목과 초록에서 추출된 주제에 따라 달라집니다. 더 깊이 들어가기 전에 테마를 분석하세요.",
  "Analizar temas": "테마 분석",
  "Ver grafo": "그래프 보기",
  "Extrae ideas de las obras clave": "주요 작품에서 아이디어 추출",
  "El grafo ya puede orientarte por temas; el siguiente salto de valor llega al analizar a fondo las obras leídas o seleccionadas.": "그래프는 이미 주제별로 방향을 정할 수 있습니다. 가치의 다음 도약은 당신이 읽거나 선택한 작품을 심층 분석하는 것에서 비롯됩니다.",
