  "Hay ideas extraídas sin índice semántico. Indexarlas mejora la fusión, las relaciones y el descubrimiento de puentes.": "의미 색인 없이 추출된 아이디어가 있습니다. 색인을 생성하면 융합, 관계 및 가교 발견이 향상됩니다.",
