  "Error al reprocesar:": "재처리 중 오류 발생:",
  "Temas principales": "주요 테마",
  "Los temas principales son los grandes nodos que agrupan tus ideas en el grafo. Añade los tuyos para controlarlos manualmente; mientras estén bloqueados, los análisis solo usarán estos temas y no generarán otros nuevos.": "주요 테마는 그래프에서 아이디어를 그룹화하는 큰 노드입니다. 수동으로 제어하려면 직접 추가하세요. 잠겨 있는 동안 분석에서는 이러한 테마만 사용하고 새 테마를 생성하지 않습니다.",
  "Reprocesar": "재처리",
  "coge las ideas ya extraídas (afirmaciones, hallazgos…) y las vuelve a agrupar bajo estos temas con el modelo seleccionado, sin volver a leer los documentos ni re-extraer ideas.": "문서를 다시 읽거나 아이디어를 다시 추출하지 않고 이미 추출된 아이디어(청구, 조사 결과…)를 선택한 모델을 사용하여 이러한 테마로 재그룹화합니다.",
  "Añadir tema principal…": "메인 테마 추가…",
