  "Con esto activado, los análisis ligeros y profundos solo asignan las obras a los temas de esta lista. Desactívalo para volver a permitir que la IA proponga temas nuevos.": "이 기능을 켜면 가볍고 심층적인 분석이 이 목록의 테마에만 작품을 할당합니다. AI가 새로운 테마를 다시 제안하도록 하려면 이 기능을 끄십시오.",
