  "Ej.: Quiero repasar cómo se relaciona el concepto de identidad nacional con la literatura de viajes y dónde hay contradicciones.": "예: 국가 정체성 개념이 여행 문학과 어떻게 관련되어 있는지, 그리고 모순이 있는지 검토하고 싶습니다.",
