  "Se genera en segundo plano: puedes cerrar esto y seguir trabajando.": "백그라운드에서 생성됩니다. 이 항목을 닫고 계속 작업할 수 있습니다.",
  "Añadir a la cola": "대기열에 추가",
  "Informe añadido a la cola. Se generará en segundo plano.": "보고서가 대기열에 추가되었습니다. 백그라운드에서 생성됩니다.",
  "Pulsa «Nuevo informe» y escribe la pregunta o idea. El informe la convierte en un texto de varias páginas, no en una respuesta corta.": "'새 보고서'를 누르고 질문이나 아이디어를 작성하세요. 보고서는 짧은 답변이 아닌 여러 페이지의 텍스트로 전환됩니다.",
  "2. Encola los que quieras": "2. 원하는 만큼 대기열에 등록하세요",
  "Añade varios informes a la cola: se generan en cadena, uno tras otro, mientras sigues trabajando.": "여러 보고서를 대기열에 추가하세요. 작업을 계속하는 동안 보고서가 차례로 생성됩니다.",
  "4. Lee a pantalla completa": "4. 전체 화면 읽기",
  "Abre cualquier informe de la galería para leerlo a pantalla completa, revisar sus citas y exportarlo a Markdown o PDF.": "갤러리에서 보고서를 열어 전체 화면으로 읽고, 인용 내용을 검토하고, Markdown이나 PDF로 내보낼 수 있습니다.",
  "Taller": "작업장",
  "Informe guardado localmente.": "보고서가 로컬에 저장되었습니다.",
  "Informe guardado abierto. Puedes exportarlo o reutilizar su idea para regenerarlo.": "저장된 보고서가 열렸습니다. 이를 내보내거나 아이디어를 재사용하여 재생성할 수 있습니다.",
  "Idea reutilizada: ajusta los parámetros y genera un informe actualizado.": "아이디어 재사용: 매개변수를 조정하고 업데이트된 보고서를 생성합니다.",
  "¿Eliminar este informe guardado? Esta acción no se puede deshacer.": "저장된 보고서를 삭제하시겠습니까? 이 작업은 취소할 수 없습니다.",
  "Informe eliminado.": "보고서가 삭제되었습니다.",
  "1. Plantea la idea": "1. 아이디어의 틀을 잡아라",
  "Escribe la pregunta o idea de investigación que quieres desarrollar. El informe la convierte en un texto de varias páginas, no en una respuesta corta.": "개발하고 싶은 연구 질문이나 아이디어를 작성하세요. 보고서는 짧은 답변이 아닌 여러 페이지의 텍스트로 전환됩니다.",
  "2. Ajusta el alcance": "2. 범위 설정",
  "Elige la extensión objetivo y el número máximo de secciones. Menos secciones producen un texto más profundo; más secciones, uno más panorámico.": "대상 길이와 최대 섹션 수를 선택하십시오. 섹션 수가 적을수록 더 깊은 텍스트가 생성됩니다. 더 많은 섹션, 더 파노라마적인 섹션.",
  "3. Cobertura del corpus": "3. 코퍼스 적용 범위",
  "Nodus recorre todo el corpus indexado, planifica las secciones y redacta guiado por la cobertura, citando cada obra sin que tengas que seleccionarla.": "Nodus는 색인된 말뭉치 전체를 휩쓸고, 섹션을 계획하고, 취재 내용에 따라 글을 작성하며, 선택하지 않고도 모든 작품을 인용합니다.",
  "4. Revisa y exporta": "4. 검토 및 내보내기",
  "Abre las citas para comprobar cada fuente, guarda el informe para retomarlo y expórtalo a Markdown o PDF cuando esté listo.": "인용문을 열어 각 소스를 확인하고 보고서를 저장하여 나중에 다시 시작하고 준비되면 Markdown 또는 PDF로 내보냅니다.",
  "Informe académico de varias páginas, guiado por cobertura y con todas las fuentes citadas.": "여러 페이지로 구성된 학술 보고서, 적용 범위 안내 및 모든 출처 인용.",
  "Adaptativo (según corpus)": "적응형(말뭉치에서)",
  "Conciso (5–8 pág.)": "간결함(5~8쪽)",
  "Estándar (9–14 pág.)": "표준(9~14페이지)",
  "Exhaustivo (15–20 pág.)": "전체(15~20페이지)",
  "Extensión objetivo del informe": "목표 보고서 길이",
  "Extensión:": "길이:",
  "Secciones:": "섹션:",
  "Número máximo de secciones (menos secciones = mayor profundidad)": "최대 섹션 수(섹션 수가 적을수록 깊이가 커짐)",
  "Secciones: Auto (IA decide)": "섹션: 자동(AI가 결정)",
  "Bloque único · sin secciones": "단일 연속 블록 · 섹션 없음",
  "Estructura del informe": "보고서 구조",
  "Una narración continua sin encabezados internos; conserva toda la recuperación y el análisis.": "내부 제목이 없는 하나의 연속적인 서술. 모든 검색 및 분석은 보존됩니다.",
  "El esquema manual fija exactamente las partes y su orden.": "매뉴얼 개요는 정확한 부품과 순서를 수정합니다.",
  "La estructura organiza el informe, pero nunca limita la evidencia relevante.": "구조는 보고서를 구성하지만 관련 증거를 제한하지 않습니다.",
  "Secciones: Auto": "섹션: 자동",
  "Máx. {n} secciones": "최대 {n} 섹션",
  "Máx. 4 secciones": "최대 4개 섹션",
  "Máx. 5 secciones": "최대 5개 섹션",
