  "Máx. 8 secciones": "최대 8개 섹션",
  "Máx. 10 secciones": "최대 10개 섹션",
  "Markdown (.md)": "Markdown(.md)",
  "PDF (.pdf)": "PDF(.pdf)",
  "Vincular a proyecto (opcional)": "프로젝트 링크(선택사항)",
  "Sin proyecto": "프로젝트 없음",
  "Generar informe": "보고서 생성",
  "Generando informe…": "보고서 생성 중…",
  "No se pudo generar el informe.": "보고서를 생성할 수 없습니다.",
  "Escribe la idea de investigación antes de generar el informe.": "보고서를 생성하기 전에 연구 아이디어를 작성하세요.",
  "Escribe la idea o pregunta de investigación. El informe la desarrollará por completo, citando todas las obras del corpus.": "연구 아이디어나 질문을 작성합니다. 보고서는 코퍼스의 모든 작업을 인용하여 이를 완전히 개발할 것입니다.",
  "Cobertura del corpus completo": "전체 코퍼스 범위",
  "Sin selección manual: el informe elige y cita las fuentes por ti.": "수동 선택 없음: 보고서가 출처를 선택하고 인용합니다.",
  "Puedes cambiar de sección: el informe seguirá en segundo plano y recuperarás este progreso al volver.": "섹션을 전환할 수 있습니다. 보고서는 백그라운드에서 계속되며 다시 돌아오면 이 진행 상황이 반환됩니다.",
  "Informe generado: {s} secciones · ~{p} páginas · {i} ideas citadas.": "생성된 보고서: {s}개 섹션 · ~{p}개 페이지 · {i}개의 아이디어가 인용되었습니다.",
  "Informe generado y guardado: {s} secciones · ~{p} páginas · {i} ideas citadas.": "생성 및 저장된 보고서: {s} 섹션 · ~{p} 페이지 · {i} 인용 아이디어.",
  "Informe generado, pero no se pudo guardar automáticamente: {error}": "보고서가 생성되었지만 자동으로 저장할 수 없습니다: {error}",
  "El informe está listo y puedes guardarlo manualmente.": "보고서가 준비되었으며 수동으로 저장할 수 있습니다.",
  "El informe aparecerá aquí. Escribe tu idea de investigación y pulsa «Generar informe».": "보고서가 여기에 표시됩니다. 연구 아이디어를 작성하고 “보고서 생성”을 누르세요.",
  "Planifica, redacta sección a sección guiado por la cobertura del corpus y ensambla un informe académico de 5–20 páginas con todas las fuentes citadas.": "계획을 세우고, 코퍼스 범위에 따라 섹션별로 섹션을 작성하고, 인용된 모든 출처를 포함하여 5~20페이지 분량의 학술 보고서를 작성하세요.",
  "Reuniendo el corpus": "코퍼스 수집",
