  "Escribe un objetivo y prepara la mesa para seleccionar materiales.": "목표를 작성하고 재료를 선택할 수 있는 표를 준비합니다.",
  "Generando borrador...": "초안 생성 중...",
  "El borrador aparecerá aquí cuando selecciones materiales y lo generes.": "재료를 선택하고 생성하면 초안이 여기에 표시됩니다.",
  "Copiar": "복사",
