  "Aún no hay borradores guardados. Genera uno y guárdalo para volver a abrirlo o reutilizar su prompt más adelante.": "아직 저장된 초안이 없습니다. 하나를 생성하고 저장하여 다시 열거나 나중에 프롬프트를 재사용하세요.",
