  "Bibliografía": "서지",
  "1. Delimita": "1. 정의",
  "Escribe el apartado que quieres construir: pregunta, capítulo, debate, hueco o marco teórico. Cuanto más concreto sea el objetivo, mejor se ordena la mesa.": "질문, 장, 토론, 공백 또는 이론적 틀 등 구축하고 싶은 섹션을 작성하세요. 목표가 구체적일수록 테이블이 더 잘 구성됩니다.",
  "2. Monta la mesa": "2. 테이블 세팅",
  "Pulsa Preparar mesa y revisa ideas, temas, huecos, contradicciones, obras y rutas. Usa Todas las ideas cuando quieras una revisión amplia del corpus encontrado.": "테이블 준비를 클릭하고 아이디어, 주제, 격차, 모순, 작품 및 경로를 검토합니다. 발견된 말뭉치에 대한 광범위한 검토를 원할 경우 모든 아이디어를 사용하십시오.",
  "3. Decide el foco": "3. 초점을 결정하세요",
  "Selecciona todo para explorar, vacía para empezar de cero o ajusta cada pestaña. La matriz final te dirá qué papel cumple cada material en el argumento.": "탐색할 모든 항목을 선택하고, 지우고 처음부터 시작하거나 각 탭을 조정하세요. 마지막 매트릭스는 논쟁에서 각 자료가 어떤 역할을 하는지 알려줍니다.",
  "4. Convierte en texto": "4. 텍스트로 변환",
  "Genera el borrador, abre las citas para verificar fuentes, guárdalo si quieres retomarlo y exporta Markdown cuando el hilo argumental ya tenga sentido para tu manuscrito.": "초안을 생성하고, 인용문을 열어 출처를 확인하고, 다시 돌아가고 싶다면 저장하고, 논쟁 스레드가 원고에 적합하면 Markdown을 내보냅니다.",
  "{n} evidencias": "{n} 증거",
