  "Fallos": "경과",
  "Próxima revisión": "다음 리뷰",
  "Listo": "완료",
  "Descartada": "폐기됨",
  "Sube un capítulo o artículo para convertirlo en texto editable. Se guardará como nota vinculada y versionada.": "편집 가능한 텍스트로 만들려면 장이나 기사를 업로드하세요. 링크된 버전의 노트로 저장됩니다.",
  "Genera sugerencias de inserción con citas verificables y revisa las citas del capítulo antes de exportar.": "검증 가능한 인용으로 삽입 제안을 생성하고 내보내기 전에 장 인용을 검토하세요.",
  "Sección actualizada. El flujo guiado refleja el cambio.": "섹션이 업데이트되었습니다. 안내된 흐름은 변경 사항을 반영합니다.",
  "Relaciones": "처지",
  "Analizar relaciones": "관계 분석",
  "{n} ideas del capítulo": "{n} 장 아이디어",
  "Extrae las ideas de este capítulo (no se añaden al grafo) y busca cómo se relacionan con tu biblioteca: ideas, notas, pasajes y obras.": "이 장의 아이디어(그래프에 추가되지 않음)를 추출하고 아이디어, 메모, 구절 및 작품 등 도서관과 어떤 관련이 있는지 찾아보세요.",
  "Analiza las relaciones para ver cómo conecta este capítulo con toda tu biblioteca.": "관계를 분석하여 이 장이 전체 라이브러리와 어떻게 연결되는지 확인하세요.",
  "Sin relaciones encontradas en la biblioteca.": "도서관에서 관계를 찾을 수 없습니다.",
  "La búsqueda de relaciones necesita un proveedor de embeddings configurado en Ajustes.": "관계를 찾으려면 설정에 구성된 임베딩 공급자가 필요합니다.",
  "No se pudieron extraer ideas de este capítulo.": "이 장에서는 아이디어를 추출할 수 없습니다.",
  "Analizadas {n} idea(s) del capítulo y sus relaciones con la biblioteca.": "{n} 장 아이디어와 도서관과의 관계를 분석했습니다.",
  "matiza": "개선하다",
  "amplía": "연장하다",
  "Verificación": "확인",
  "Verificar citas": "인용 확인",
  "Revisado con IA": "AI 검토",
  "Revisión determinista": "결정론적 검토",
  "Detecta afirmaciones del capítulo, comprueba si ya tienen cita y solo marca las que coinciden con ideas o pasajes del corpus.": "장의 주장을 감지하고, 이미 인용이 있는지 확인하고, 일치하는 말뭉치 아이디어나 구절에만 플래그를 지정하세요.",
  "Afirmaciones": "청구",
  "Faltan citas": "인용 누락",
  "Cubiertas": "덮음",
  "Aportación propia": "자체 기여",
  "No hay suficientes señales del corpus para verificar este capítulo.": "이 장을 검증하기에는 코퍼스 신호가 충분하지 않습니다.",
  "Verificadas {n} afirmaciones; {m} necesitan cita.": "{n}개의 주장이 확인되었습니다. {m} 인용이 필요합니다.",
  "Verifica el capítulo contra tu corpus antes de cerrar el manuscrito o exportarlo.": "원고를 닫거나 내보내기 전에 말뭉치와 비교하여 장을 확인하세요.",
  "No se encontraron afirmaciones que requieran revisión de citas.": "인용 검토가 필요한 주장이 발견되지 않았습니다.",
  "Falta cita": "인용 누락",
  "Cita cubierta": "인용이 다루어졌습니다",
  "Posible aportación propia": "가능한 자체 기여",
  "Coincidencia débil": "약한 일치",
  "Con cita": "인용됨",
  "Párrafo {p} · frase {s}": "단락 {p} · 문장 {s}",
  "Sugerencia": "제안",
  "Candidatos de cita": "인용후보",
  "ordenados por afinidad": "선호도에 따라 순위가 매겨짐",
  "Sin citas sugeridas.": "추천 인용이 없습니다.",
  "Recomendada": "추천",
  "Aplicar cita": "인용 적용",
  "Ver fuente": "소스 보기",
  "Cita aplicada al borrador sobre una versión nueva recuperable.": "복구 가능한 새 버전의 초안에 인용이 적용되었습니다.",
  "No se pudo localizar la frase exacta en el borrador; insértala manualmente desde el texto.": "초안에서 정확한 문장을 찾을 수 없습니다. 텍스트에서 수동으로 삽입하세요.",
  "Eliminar proyecto": "프로젝트 삭제",
  "Proyecto eliminado.": "프로젝트가 삭제되었습니다.",
  "¿Eliminar el proyecto «{title}»? Se borrarán sus secciones, vínculos y capítulos. Las notas y carpetas creadas se conservan. Esta acción no se puede deshacer.": "“{title}” 프로젝트를 삭제하시겠습니까? 해당 섹션, 링크 및 장이 제거됩니다. 생성된 메모와 폴더는 유지됩니다. 이 작업은 취소할 수 없습니다.",
  "Todas las notas": "모든 메모",
  "Sin carpeta": "폴더 없음",
  "Nueva carpeta": "새 폴더",
  "Carpeta nueva": "새 폴더",
  "Nueva subcarpeta": "새 하위 폴더",
  "Crear carpeta": "폴더 생성",
  "Nota sin título": "제목 없는 메모",
  "Título de la nota": "메모 제목",
  "Mover a carpeta": "폴더로 이동",
  "Sin carpeta (raíz)": "폴더 없음(루트)",
  "Buscar en notas…": "메모 검색…",
  "Guardar en notas": "메모에 저장",
  "Auditoría de la relación": "관계 감사",
  "Abrir el PDF en Zotero por esta página": "이 페이지의 Zotero에서 PDF를 엽니다.",
  "Auditoría": "심사",
  "Auditoría de relaciones": "관계 감사 원장",
  "Ver y deshacer tus veredictos sobre relaciones (confirmadas y rechazadas)": "관계 판정(확인 및 거부)을 검토하고 취소합니다.",
  "Aún no has auditado ninguna relación. Abre una arista en el grafo y usa «Confirmar» o «Marcar como incorrecta».": "아직 어떤 관계도 감사하지 않았습니다. 그래프에서 가장자리를 열고 \"확인\" 또는 \"잘못된 것으로 표시\"를 사용하세요.",
  "Rechazadas (ocultas del grafo y de los análisis)": "거부됨(그래프 및 분석에서 숨겨짐)",
  "Confirmadas por ti": "귀하가 확인함",
  "Has confirmado esta relación.": "이 관계를 확인하셨습니다.",
  "Has marcado esta relación como incorrecta: desaparecerá del grafo y de los análisis.": "이 관계를 잘못된 것으로 표시했습니다. 그래프와 분석에서 사라집니다.",
  "Marcar esta relación como verificada por ti": "이 관계를 귀하가 확인한 것으로 표시하세요",
  "Ocultar esta relación del grafo y de los análisis (persiste tras re-análisis)": "그래프 및 분석에서 이 관계를 숨깁니다(재분석 시 지속됨).",
  "Marcar como incorrecta": "잘못된 것으로 표시",
  "Quitar el veredicto y volver al estado derivado": "판정을 제거하고 파생된 상태로 돌아가기",
  "Sincronización entre equipos": "다중 장치 동기화",
  "Copias de seguridad automáticas": "자동 백업",
  "Copias cifradas periódicas en una carpeta a tu elección. Cada copia incluye todo Nodus; puedes usar iCloud Drive, Google Drive o Dropbox para mantenerla fuera de este equipo.": "선택한 폴더에 정기적으로 암호화된 복사본을 저장합니다. 모든 백업에는 Nodus가 모두 포함됩니다. iCloud Drive, Google Drive 또는 Dropbox를 사용하여 이 컴퓨터에서 차단하세요.",
  "Cada copia protege todo Nodus automáticamente.": "모든 백업은 모든 Nodus를 자동으로 보호합니다.",
  "Incluye todas las bóvedas, documentos, preferencias, historiales, archivos generados y claves API. No existen exclusiones configurables.": "여기에는 모든 Vault, 문서, 기본 설정, 기록, 생성된 파일 및 API 키가 포함됩니다. 구성 가능한 제외가 없습니다.",
