  "Contraseña maestra guardada. Descarga el kit de recuperación: sin la contraseña, las copias no se pueden restaurar.": "마스터 비밀번호가 저장되었습니다. 복구 키트 다운로드: 비밀번호가 없으면 백업을 복원할 수 없습니다.",
  "Contraseña maestra guardada. Descarga el kit: permite recuperar incluso si olvidas la contraseña.": "마스터 비밀번호가 저장되었습니다. 키트를 다운로드하세요. 비밀번호를 잊어버린 경우에도 복구할 수 있습니다.",
  "Credenciales de recuperación de la copia": "백업 복구 자격 증명",
  "Guarda ambas fuera de este dispositivo. Podrás importar la copia con cualquiera de ellas.": "둘 다 이 장치에서 멀리 떨어진 곳에 보관하세요. 둘 중 하나로 백업을 가져올 수 있습니다.",
