  "Lleva tus notas, borradores, búsquedas guardadas, auditorías de relaciones y bases de datos a otro equipo. Al importar se fusiona: gana la versión más reciente y nunca se borra nada local.": "메모, 초안, 저장된 검색, 관계 감사 및 데이터베이스를 다른 컴퓨터로 가져가세요. 병합 가져오기: 최신 버전이 우선하며 로컬 항목은 삭제되지 않습니다.",
