  "Crea carpetas para organizar tus notas como capítulos y subepígrafes.": "폴더를 만들어 노트를 장과 부제목으로 정리하세요.",
  "No hay notas aquí todavía. Crea una o guarda respuestas del asistente.": "아직 메모가 없습니다. 하나를 만들거나 어시스턴트 답변을 저장하세요.",
