  "Carga un corpus de demostración de seis obras sobre la ciencia del aprendizaje. Podrás recorrer el grafo, ideas, debates, huecos y notas sin conectar Zotero ni configurar una clave de IA.": "학습 과학에 관한 6개 작품의 데모 코퍼스를 로드합니다. Zotero를 연결하거나 AI 키를 구성하지 않고도 그래프, 아이디어, 토론, 공백 및 메모를 탐색할 수 있습니다.",
  "Cargar demo": "데모 로드",
  "Explora con datos de ejemplo": "샘플 데이터로 탐색",
  "Prueba sin configurar nada": "아무것도 설정하지 않고 사용해 보세요",
  "Crea resúmenes de orientación independientes a partir de ideas, evidencia, temas y abstract. No son evidencia citable.": "아이디어, 증거, 주제 및 초록을 바탕으로 독립형 오리엔테이션 요약을 만듭니다. 이는 인용 가능한 증거가 아닙니다.",
  "El análisis profundo solo usó el abstract, no el texto completo (el PDF/EPUB no estaba disponible al analizar). Reanaliza cuando esté en Zotero.": "심층 분석에서는 전문이 아닌 초록만 사용했습니다(분석 시 PDF/EPUB를 사용할 수 없음). Zotero에 들어가면 다시 분석해 보세요.",
  "El texto o el modelo de embeddings cambió.": "텍스트 또는 임베딩 모델이 변경되었습니다.",
  "Las ideas pertenecen a la versión anterior del texto. Vuelve a analizarlas para usar el texto actual.": "아이디어는 이전 텍스트 버전에 속합니다. 현재 텍스트를 사용하려면 다시 분석하세요.",
  "El texto cambió; vuelve a indexar sus fragmentos.": "텍스트가 변경되었습니다. 해당 구절을 다시 색인화하십시오.",
  "Los fragmentos se indexaron con otro modelo de embeddings.": "해당 구절은 다른 임베딩 모델을 사용하여 색인화되었습니다.",
  "El texto y el modelo de embeddings cambiaron.": "텍스트와 임베딩 모델이 모두 변경되었습니다.",
  "Algunos fragmentos no tienen un embedding válido.": "일부 구절에는 유효한 삽입이 없습니다.",
  "Generar resúmenes faltantes": "누락된 요약 생성",
  "Indexa fragmentos de texto completo en las obras que faltan o están obsoletas. No requiere análisis de ideas; el texto se mantiene como evidencia citable.": "누락되었거나 오래된 작품의 전체 텍스트 조각을 색인화합니다. 아이디어 분석이 필요하지 않습니다. 텍스트는 인용 가능한 증거로 남아 있습니다.",
  "Indexar pasajes": "색인 구절",
  "Indexar pasajes de esta obra": "이 작품의 색인 구절",
  "Indexar todo": "모두 색인화",
  "No hay obras «solo abstract» para reanalizar.": "재분석할 \"추상적인\" 작품은 없습니다.",
