  "Reanálisis en cola para {n} obra(s) «solo abstract». Verás el progreso en la cola.": "{n} «추상 전용» 작업에 대한 재분석이 대기 중입니다. 대기열에서 진행 상황을 볼 수 있습니다.",
  "Reanaliza las obras que solo se analizaron con el abstract (el PDF/EPUB no estaba disponible al analizarlas). Las que ya tengan el texto disponible en Zotero recuperarán el análisis completo; el resto se omiten sin coste. ¿Continuar?": "초록만 분석한 작품을 재분석합니다(분석 시 PDF/EPUB를 사용할 수 없음). 이제 Zotero에서 텍스트를 사용할 수 있는 사람들은 전체 분석을 복구할 것입니다. 나머지는 무료로 건너뜁니다. 계속하다?",
  "Reanalizar": "재분석",
  "Reanalizar «solo abstract»": "«추상 전용» 재분석",
  "Recorre toda la biblioteca y actualiza solo los índices que hayan cambiado. Los ya actuales se omiten.": "전체 라이브러리를 스윕하고 변경된 인덱스만 업데이트합니다. 이미 최신 버전은 건너뜁니다.",
  "resumen": "요약",
  "solo abstract": "추상적인 것만",
  "Vuelve a analizar las obras cuyo análisis profundo solo usó el abstract porque el PDF/EPUB no estaba disponible. Las que ya tengan el texto recuperan el análisis completo; el resto se omiten sin coste.": "PDF/EPUB를 사용할 수 없어 초록만 사용한 심층 분석 작업을 다시 분석합니다. 이제 텍스트를 가지고 있는 사람들은 전체 분석을 복구합니다. 나머지는 무료로 건너뜁니다.",
  "Añade citas textuales con su página o rango de páginas.": "해당 페이지 또는 페이지 범위와 함께 축어적 인용문을 추가합니다.",
