  "Floja": "약한",
  "Responde con tus palabras: tesis, autores y evidencia…": "자신의 말로 답변하십시오: 논문, 저자 및 증거…",
  "Evaluar con IA": "AI로 평가",
  "Evaluando…": "평가 중…",
