  "estaciones": "스테이션",
  "citas": "인용 부호",
  "preguntas": "질문",
  "El territorio completo": "전체 영토",
  "Falta la clave del proveedor de IA: configúrala en Ajustes": "AI 제공업체 키가 누락되었습니다. 설정에서 설정하세요.",
  "Profundiza: informe Deep Research del tema": "더 자세히 알아보기: 주제에 대한 Deep Research 보고서",
  "Ahora que dominas el tema, genera el informe académico de varias páginas con todas las fuentes citadas. Se guarda en Deep Research y podrás exportarlo o citarlo en tu escritura.": "이제 주제를 마스터했으므로 인용된 모든 출처가 포함된 여러 페이지로 구성된 학술 보고서를 생성하세요. Deep Research에 저장되므로 내보내거나 글에 인용할 수 있습니다.",
  "Puedes cambiar de sección: el informe seguirá generándose y mostrará el progreso al volver.": "섹션을 전환할 수 있습니다. 보고서는 계속 생성되며 다시 돌아오면 진행 상황이 표시됩니다.",
  "Dossier guardado: «{t}» · {s} secciones · ~{p} páginas. Lo tienes en Deep Research → informes guardados.": "저장된 Dossier: “{t}” · {s} 섹션 · ~{p} 페이지. Deep Research → 저장된 보고서에서 찾아보세요.",
  "Generar de nuevo": "다시 생성",
  "Seleccionar modelo": "모델 선택",
  "Usar modelo de síntesis": "합성 모델 사용",
  "Modelo inicial para las tareas de IA ({n} disponibles)": "AI 작업을 위한 초기 모델({n} 사용 가능)",
  "Modelos favoritos para los selectores independientes": "독립 선택자가 선호하는 모델",
  "Los modelos de análisis se configuran en Ajustes.": "분석 모델은 설정에서 구성됩니다.",
  "Modelos de análisis: Ajustes": "분석 모델: 설정",
  "coge las ideas ya extraídas (afirmaciones, hallazgos…) y las vuelve a agrupar bajo estos temas con los modelos configurados en Ajustes, sin volver a leer los documentos ni re-extraer ideas.": "문서를 다시 읽거나 아이디어를 다시 추출하지 않고도 이미 추출된 아이디어(주장, 조사 결과…)를 가져와서 설정에 구성된 모델을 사용하여 이러한 테마로 다시 그룹화합니다.",
  "Cada tarea usa su propio modelo. Los escaneos, resúmenes, fusión y embeddings obedecen estos ajustes; Chat, Deep Research, Inmersión y las demás herramientas conservan el modelo elegido dentro de su propia sección.": "각 작업은 자체 모델을 사용합니다. 스캔, 요약, 융합, 임베딩은 이 설정을 따르며, 채팅, Deep Research, 몰입 및 기타 도구는 각 섹션에서 선택한 모델을 유지합니다.",
  "Modelo de síntesis general (fallback inicial para herramientas con selector propio)": "일반 합성 모델(자체 선택기가 있는 도구에 대한 초기 대체)",
  "modelos por tarea": "작업별 모델",
  "Extracción: {provider}": "추출: {provider}",
  "Síntesis: {provider}": "합성: {provider}",
  "Configura los modelos de IA": "AI 모델 구성",
  "La sincronización puede funcionar, pero Nodus necesita modelos separados de extracción y síntesis para analizar el corpus.": "동기화는 작동할 수 있지만 Nodus는 코퍼스를 분석하기 위해 별도의 추출 및 합성 모델이 필요합니다.",
  "Generación de imágenes": "이미지 생성",
  "Configuración independiente para las imágenes decorativas opcionales. OpenAI usa su API oficial de imágenes y reutiliza la clave de OpenAI; Google reutiliza la clave de Gemini.": "선택적 장식 이미지에 대한 독립적인 설정입니다. OpenAI는 공식 이미지 API를 사용하고 OpenAI 키를 재사용합니다. Google은 Gemini 키를 재사용합니다.",
  "Actualizar modelos": "모델 새로 고침",
  "Estilo predeterminado": "기본 스타일",
  "Selección actual": "현재 선택",
  "Buscar por proveedor, nombre o identificador…": "제공자, 이름, 식별자로 검색하세요…",
  "Proveedor y nombre": "제공자 및 이름",
  "Orden alfabético": "알파벳순",
  "Precio por imagen: menor a mayor (por proveedor)": "이미지 가격: 낮음에서 높음(공급자당)",
  "Precio por imagen: mayor a menor (por proveedor)": "이미지 가격: 높음에서 낮음(공급자별)",
  "Como los proveedores publican tamaños y métricas diferentes, la ordenación por precio se aplica por separado dentro de cada proveedor. Los modelos sin precio directo quedan al final; no se estiman costes.": "공급자는 다양한 크기와 측정항목을 게시하므로 가격 정렬은 각 공급자 내에서 별도로 적용됩니다. 직접적인 가격이 없는 모델은 마지막에 나타납니다. 비용은 추정되지 않습니다.",
  "Consultando catálogos oficiales…": "공식 카탈로그 로드 중…",
