  "Descripción de la escena": "장면 설명",
  "Describe la escena que quieres ver. Si lo dejas vacío, se deduce del contenido.": "원하는 장면을 설명해주세요. 비워두면 콘텐츠에서 추론됩니다.",
  "El estilo y las protecciones de «sin texto» se aplican automáticamente al generar.": "스타일 및 \"텍스트 없음\" 보호 조치는 생성 시 자동으로 적용됩니다.",
