  "Cargado en memoria": "메모리에 로드됨",
  "Ollama debe estar en marcha y los modelos descargados con \"ollama pull\". No requiere clave.": "Ollama는 실행 중이어야 하며 \"ollama pull\"을 사용하여 모델을 당겨야 합니다. 열쇠가 필요하지 않습니다.",
  "Activa el servidor local en LM Studio (Developer → Start Server) y carga al menos un modelo. No requiere clave.": "LM Studio에서 로컬 서버를 시작하고(개발자 → 서버 시작) 하나 이상의 모델을 로드합니다. 열쇠가 필요하지 않습니다.",
