  "El servidor no reporta modelos. Descarga o carga uno primero.": "서버에서 모델이 없다고 보고합니다. 먼저 다운로드하거나 로드하세요.",
  "Proveedor local: no necesita clave. Usa la dirección por defecto; puedes cambiar IP y puerto en Ajustes → Proveedores.": "지역 공급자: 키가 필요하지 않습니다. 기본 주소를 사용하십시오. 설정 → 공급자에서 IP 및 포트를 변경할 수 있습니다.",
  "Traducir": "번역하다",
  "Traducciones": "번역",
  "Traducciones con IA": "AI 번역",
  "Traduce este contenido a otro idioma. Cada idioma se guarda y puede regenerarse o eliminarse.": "이 콘텐츠를 다른 언어로 번역하세요. 각 언어는 저장되며 재생성하거나 삭제할 수 있습니다.",
  "Generar traducción": "번역 생성",
