  "Genera la traducción con el modelo de IA configurado": "구성된 AI 모델로 번역을 생성합니다.",
  "La traducción de un texto largo puede tardar. Puedes cerrar esta ventana: se guardará y aparecerá aquí al volver.": "긴 텍스트를 번역하는 데 시간이 걸릴 수 있습니다. 이 창을 닫아도 됩니다. 창은 저장되어 다시 돌아올 때 여기에 표시됩니다.",
  "Cargando traducciones…": "번역 로드 중…",
  "Aún no hay traducciones. Elige un idioma y genera la primera.": "아직 번역이 없습니다. 언어를 선택하고 첫 번째 언어를 생성하세요.",
  "Regenerar esta traducción": "이 번역을 다시 생성하세요.",
  "Eliminar traducción": "번역 삭제",
  "¿Eliminar la traducción a {lang}? Esta acción no se puede deshacer.": "{lang} 번역을 삭제하시겠습니까? 이 작업은 취소할 수 없습니다.",
  "Seleccionar todo": "모두 선택",
  "Deseleccionar todo": "모두 선택 취소",
  "Eliminar seleccionados": "선택 항목 삭제",
  "Eliminar seleccionadas": "선택 항목 삭제",
  "Eliminar informes": "보고서 삭제",
  "¿Eliminar {n} informes guardados? Esta acción no se puede deshacer.": "{n}개의 저장된 보고서를 삭제하시겠습니까? 이 작업은 취소할 수 없습니다.",
  "{n} informes eliminados.": "{n} 보고서가 삭제되었습니다.",
  "Eliminar inmersiones": "몰입 삭제",
  "¿Eliminar {n} inmersiones y todo su progreso? Esta acción no se puede deshacer.": "{n} 몰입과 모든 진행 상황을 삭제하시겠습니까? 이 작업은 취소할 수 없습니다.",
  "Nueva inmersión": "새 몰입",
  "Domina un tema de tu corpus: panorama, estaciones con citas literales, contrastes, fronteras y examen final. Todo queda grabado para retomarlo.": "코퍼스의 주제를 익히세요: 개관, 그대로 인용한 스테이션, 대조, 경계, 최종 시험. 모든 기록이 저장되어 나중에 이어서 할 수 있습니다.",
  "Domina un tema de tu corpus: el contenido y el progreso se guardan para retomarlos; tus respuestas se borran al reiniciar.": "코퍼스에서 주제를 마스터하세요. 다시 시작할 수 있도록 콘텐츠와 진행 상황이 저장되며, 다시 시작하면 답변이 지워집니다.",
  "Buscar entre tus inmersiones…": "몰입 검색…",
  "Cargando inmersiones…": "몰입 불러오는 중…",
  "Ninguna inmersión coincide con tu búsqueda.": "검색어와 일치하는 몰입이 없습니다.",
  "Aún no hay inmersiones. Crea la primera y quedará aquí, con su progreso y tus respuestas, lista para retomarla.": "아직 몰입이 없습니다. 첫 번째 항목을 생성하면 진행 상황 및 답변과 함께 여기에 그대로 유지되어 재개할 준비가 됩니다.",
  "Aún no hay inmersiones. Crea la primera y quedará aquí, con su progreso, lista para retomarla.": "아직 몰입이 없습니다. 첫 번째 항목을 생성하면 여기에 진행 상태가 유지되어 재개할 준비가 됩니다.",
  "Reiniciar borra las respuestas anteriores y comienza el recorrido desde el principio.": "다시 시작하면 이전 답변이 지워지고 경로가 처음부터 시작됩니다.",
  "Elige el tema y el alcance. Antes de generar verás qué sabe tu corpus (sin IA).": "주제와 범위를 선택하세요. 생성하기 전에 코퍼스가 무엇을 알고 있는지 확인할 수 있습니다(아직 AI 없음).",
  "Duración": "지속",
  "Novedades": "새로운 소식",
  "Esto es lo nuevo en esta versión de Nodus.": "이번 Nodus 버전의 새로운 기능은 다음과 같습니다.",
  "¡Entendido!": "알았어요",
