  "Elige las colecciones a monitorizar. Despliega cualquier colección para elegir subcolecciones concretas si una es demasiado grande. Se incorporan metadatos; los análisis se lanzan manualmente salvo que actives automatización en Ajustes.": "모니터링할 컬렉션을 선택합니다. 컬렉션이 너무 큰 경우 컬렉션을 확장하여 특정 하위 컬렉션을 선택하세요. 메타데이터를 가져옵니다. 설정에서 자동화를 활성화하지 않으면 분석이 수동으로 실행됩니다.",
  "Fuentes primarias": "1차 사료",
  "Genealogía": "계보",
