  "próximamente": "곧 온다",
  "Tipo de bóveda: {type}.": "저장소 유형: {type}.",
  "Mi bóveda": "내 Vault",
  "TU PRIMERA BÓVEDA": "당신의 첫 번째 Vault",
  "Vamos a crear tu primera bóveda": "첫 번째 Vault를 설정해 보겠습니다.",
  "Ponle un nombre y elige su modo. El modo decide qué secciones verás y cómo trabaja la IA contigo; puedes crear más bóvedas, de otros modos, cuando quieras.": "이름을 지정하고 모드를 선택하세요. 모드에 따라 표시되는 섹션과 AI가 작동하는 방식이 결정됩니다. 원할 때마다 다른 모드로 더 많은 Vault를 생성할 수 있습니다.",
  "Después el asistente te ayudará a elegir su modelo de IA y su modelo de embeddings. Puedes cambiar el nombre en cualquier momento desde el selector de bóvedas.": "그러면 마법사가 AI 모델과 임베딩 모델을 선택하는 데 도움을 줍니다. Vault 전환기에서 언제든지 Vault 이름을 바꿀 수 있습니다.",
