  "Aún no hay personas. Se crean al analizar fuentes primarias o añadiéndolas a mano.": "아직 사람이 없습니다. 기본 소스를 분석하거나 직접 추가할 때 나타납니다.",
  "sin fechas": "날짜 없음",
  "Selecciona una persona para ver su ficha, sus eventos y la evidencia que la respalda.": "한 사람을 선택하면 그 사람의 기록, 사건, 그 뒤에 숨은 증거를 볼 수 있습니다.",
  "Propuestos a partir de la evidencia de las fuentes. Tú confirmas; nada se añade al árbol solo.": "출처의 증거를 바탕으로 제안되었습니다. 귀하는 확인합니다. 그 자체로는 트리에 아무것도 추가되지 않습니다.",
