  "Las fechas pueden ser inciertas: \"c. 1850\", \"antes de 1880\".": "날짜는 불확실할 수 있습니다: \"1850년경\", \"1880년 이전\".",
  "Aún no hay evidencia suficiente para redactar una biografía.": "아직 자서전을 쓰기에는 증거가 충분하지 않습니다.",
  "¿Eliminar esta persona y su evidencia? Los eventos en que participa se conservan.": "이 사람과 그 증거물을 삭제하시겠습니까? 그들이 참여하는 이벤트가 유지됩니다.",
