  "Se sustituirá el archivo de «{title}» por otro y se volverá a extraer su texto. Se conservan el título, la clasificación, las etiquetas y las personas vinculadas. ¿Continuar?": "“{title}” 파일은 다른 파일로 대체되고 해당 텍스트가 다시 추출됩니다. 제목, 분류, 태그, 링크된 인물은 그대로 유지됩니다. 계속하다?",
  "Elegir archivo…": "파일 선택…",
  "Archivo reemplazado.": "파일이 교체되었습니다.",
  "Este elemento no es una imagen analizable.": "이 항목은 분석 가능한 이미지가 아닙니다.",
  "Imagen analizada.": "이미지가 분석되었습니다.",
  "Este elemento no tiene texto extraído para analizar.": "이 항목에는 분석할 추출된 텍스트가 없습니다.",
  "Extraídos: {p} personas, {e} eventos.": "추출됨: {p}명, {e}개 이벤트.",
  "{n} enlazadas a personas existentes.": "{n}이(가) 기존 사용자에게 연결되었습니다.",
  "{n} parentescos sugeridos por revisar.": "{n}에서는 검토할 관계를 제안했습니다.",
  "Describir la imagen y transcribir su texto con el modelo de visión": "비전 모델을 사용하여 이미지를 설명하고 해당 텍스트를 기록합니다.",
  "Analizar imagen": "이미지 분석",
  "Extraer personas, lugares y eventos de este documento": "이 문서에서 사람, 장소, 이벤트를 추출하세요.",
  "Extraer personas y eventos": "인물 및 이벤트 추출",
  "Sustituir el archivo adjunto por otro (se vuelve a extraer su texto)": "첨부파일을 다른 파일로 교체하세요. (해당 텍스트는 다시 추출됩니다.)",
  "Reemplazando…": "교체 중…",
  "Reemplazar archivo": "파일 교체",
  "Texto extraído": "추출된 텍스트",
  "Sin texto extraído.": "추출된 텍스트가 없습니다.",
  "¿De dónde procede? Archivo, repositorio, cita, URL…": "그것은 어디에서 왔습니까? 아카이브, 저장소, 인용, URL…",
  "Fuente (opcional): archivo, repositorio, cita, URL…": "출처(선택): 아카이브, 저장소, 인용, URL…",
  "Clasificación": "분류",
  "Clasificación conceptual dentro de la asignatura.": "주제 내의 개념적 분류.",
  "Guardar clasificación": "분류 저장",
  "Personas mencionadas en este documento": "이 문서에 언급된 사람들",
  "Coinciden con miembros del árbol. Vincúlalas si son la misma persona.": "그들은 트리의 구성원과 일치합니다. 동일인이면 연결해주세요.",
  "Añadir etiqueta…": "태그 추가…",
  "Editar descripción y texto": "설명 및 텍스트 수정",
  "Descripción": "설명",
  "Guardar cambios": "변경사항 저장",
