  "{s} estaciones · {i} ideas · {w} obras · ~{m} minutos": "스테이션 {s}개 · 아이디어 {i}개 · 작품 {w}개 · 약 {m}분",
  "Elige y prepara una voz en Ajustes → IA → Audio y voz.": "설정 → AI → 오디오 및 음성에서 음성을 선택하고 설정하세요.",
  "No hay texto narrable en este contenido.": "이 콘텐츠에는 설명 가능한 텍스트가 없습니다.",
  "Audio": "오디오",
  "{n} pistas": "{n} 트랙",
  "Reproducir todo": "모두 재생",
  "Eliminar audio": "오디오 삭제",
  "Generar audio": "오디오 생성",
  "Elige y prepara una voz en Ajustes → IA → Audio y voz para poder narrar.": "설정 → AI → 오디오 및 음성에서 내레이션할 음성을 선택하고 설정하세요.",
  "Faltan algunos archivos de audio (no se guardan en las copias de seguridad). Pulsa Regenerar para recuperarlos.": "일부 오디오 파일이 누락되었습니다(백업에 보관되지 않음). 복구하려면 재생성을 누르세요.",
  "Archivo no disponible": "파일을 사용할 수 없음",
