  "Reproducir": "놀다",
  "sin archivo": "파일 없음",
  "Eliminar pista": "트랙 삭제",
  "Velocidad de reproducción": "재생 속도",
  "Velocidad": "속도",
  "Detener y cerrar": "중지하고 닫습니다.",
  "Audio y voz": "오디오 및 음성",
  "Narra tus informes de Deep Research y tus inmersiones con una voz. La generación se hace por secciones y en segundo plano; puede tardar según la longitud.": "Deep Research 보고서와 몰입 내용을 음성으로 설명하세요. 생성은 백그라운드에서 섹션별로 실행됩니다. 길이에 따라 시간이 걸릴 수 있습니다.",
  "Nube · clave propia": "클라우드 · 나만의 키",
  "Local · sin conexión": "로컬·오프라인",
  "Proveedor de voz": "음성 제공업체",
  "Clave guardada": "키가 저장되었습니다",
  "Cargando voces…": "음성 로드 중…",
  "Recargar voces": "음성 다시 로드",
  "Borrar clave": "클리어 키",
  "Clave de API de Hume (se guarda cifrada, nunca se exporta)": "Hume API 키(암호화되어 저장되며 내보내지 않음)",
  "Guardar clave": "키 저장",
  "El audio se genera con tu cuenta de Hume y se factura a tu clave. El texto de la sección se envía a Hume para sintetizarlo.": "오디오는 귀하의 Hume 계정으로 생성되며 귀하의 키로 청구됩니다. 섹션 텍스트는 합성을 위해 Hume으로 전송됩니다.",
  "Modelo {label}": "{label} 모델",
  "~{n} MB · una sola descarga para todas las voces": "~{n}MB · 모든 음성에 대한 단일 다운로드",
  "{n}%": "{n}%",
  "Descargar modelo": "모델 다운로드",
  "No se encontraron voces para esta clave.": "이 키에 대한 음성을 찾을 수 없습니다.",
  "Usar esta voz": "이 목소리를 사용하세요",
