  "Nuevo lugar": "새로운 장소",
  "Busca un lugar y registra su relación con esta persona.": "장소를 검색하고 이 사람과의 관계를 기록하세요.",
  "Registra los lugares de esta persona (municipio, estado, país). Construyen su mapa individual y alimentan el mapa general.": "이 사람의 장소(자치단체, 주, 국가)를 기록하세요. 그들은 개별 지도를 만들고 일반 지도를 제공합니다.",
  "Sin lugares registrados.": "등록된 장소가 없습니다.",
  "sin coordenadas": "좌표 없음",
  "Guardar lugar": "장소 저장",
  "Eliminar lugar": "장소 삭제",
  "¿Eliminar «{name}» de los lugares de esta persona?": "이 사람의 장소에서 '{name}'을(를) 삭제하시겠습니까?",
  "Eliminar persona": "사람 삭제",
  "Eliminar evento": "일정 삭제",
  "Buscar un lugar (municipio, ciudad…)": "장소 검색(지방자치단체, 도시…)",
  "Sin coincidencias. Prueba con el nombre en su idioma original.": "일치하는 항목이 없습니다. 원래 언어로 이름을 입력해 보세요.",
  "+{n} más": "+{n}개 더보기",
  "Ningún lugar localizado todavía. Añade lugares a las personas (con su municipio, estado y país) para verlos en el mapa.": "아직 장소를 찾을 수 없습니다. 사람들에게 장소(자치단체, 주, 국가 포함)를 추가하면 지도에서 볼 수 있습니다.",
  "Ningún lugar localizado todavía. Abre la ficha de una persona y añade sus lugares (municipio, estado, país); aparecerán aquí sobre el mapa.": "아직 장소를 찾을 수 없습니다. 개인의 기록을 열고 장소(자치단체, 주, 국가)를 추가합니다. 여기 지도에 나타날 것입니다.",
