  "Eliminar fila": "행 삭제",
  "¿Eliminar esta fila?": "이 행을 삭제하시겠습니까?",
  "Eliminar base de datos": "데이터베이스 삭제",
  "¿Eliminar la base de datos «{name}»? Se borrarán todas sus filas y columnas.": "\"{name}\" 데이터베이스를 삭제하시겠습니까? 모든 행과 열이 제거됩니다.",
  "Selecciona o crea una base de datos": "데이터베이스 선택 또는 생성",
  "Las bases de datos aparecen en la barra lateral. Crea la primera para empezar.": "데이터베이스가 사이드바에 나타납니다. 시작하려면 첫 번째 항목을 만드세요.",
  "entradas": "항목",
