  "Columna": "열",
  "Añadir columna": "열 추가",
  "El análisis estadístico y los informes con IA sobre tus bases de datos llegarán en una próxima fase.": "데이터베이스에 대한 통계 분석 및 AI 보고서는 이후 단계에서 제공될 예정입니다.",
  "El chat de datos, con gráficos y consultas reproducibles sobre tus bases de datos, llegará en una próxima fase.": "데이터베이스에 대한 차트와 재현 가능한 쿼리가 포함된 데이터 채팅은 이후 단계에서 제공될 예정입니다.",
  "Tus datos estructurados: tablas con columnas tipadas, análisis y chat.": "구조화된 데이터: 입력된 열이 포함된 테이블, 분석 및 채팅.",
