  "¿Eliminar este adjunto? Esta acción no se puede deshacer.": "이 첨부파일을 삭제하시겠습니까? 이 작업은 취소할 수 없습니다.",
  "Resume el contenido de esta fila en una o dos frases claras.": "이 행을 하나 또는 두 개의 명확한 문장으로 요약하세요.",
  "Clasifica esta fila en una categoría breve (una o dos palabras). Devuelve solo la categoría.": "이 행을 짧은 카테고리(한두 단어)로 분류하세요. 카테고리만 반환합니다.",
  "Extrae de 3 a 5 palabras clave separadas por comas. Devuelve solo las palabras clave.": "쉼표로 구분된 3~5개의 키워드를 추출합니다. 키워드만 반환합니다.",
  "Indica el sentimiento del contenido: positivo, negativo o neutro. Devuelve solo una palabra.": "콘텐츠의 감정을 명시합니다(긍정적, 부정적 또는 중립). 한 단어만 반환합니다.",
  "Traduce el contenido principal de esta fila al inglés. Devuelve solo la traducción.": "이 행의 주요 내용을 영어로 번역하세요. 번역만 반환합니다.",
  "Describe en 40-60 palabras la imagen adjunta a esta fila.": "이 행에 첨부된 이미지를 40~60 단어로 설명하세요.",
  "Transcribe literalmente todo el texto que aparezca en la imagen o archivo adjunto. Devuelve solo la transcripción.": "첨부된 이미지나 파일에 나타나는 모든 텍스트를 문자 그대로 옮겨 적습니다. 전사본만 반환합니다.",
