  "Demo de bases de datos": "데이터베이스 데모",
  "Tres tablas de investigación con todos los tipos de columna, relaciones, registros, análisis, una conversación y notas de ejemplo. Incluye un tutorial guiado.": "모든 열 유형, 관계, 기록, 분석, 대화 및 샘플 메모가 포함된 세 가지 연구 테이블입니다. 안내 튜토리얼이 포함되어 있습니다.",
  "Cargar demo de bases de datos": "데이터베이스 데모 로드",
  "Cargar datos de ejemplo": "샘플 데이터 로드",
  "Tutorial de bases de datos": "데이터베이스 튜토리얼",
  "La lista de bases de datos, la tabla con columnas tipadas, la edición de celdas y las secciones de análisis y chat.": "데이터베이스 목록, 입력된 열이 있는 테이블, 셀 편집, 분석 및 채팅 섹션.",
  "Se mostrará el tutorial de bases de datos.": "데이터베이스 튜토리얼이 표시됩니다.",
  "Bienvenido al modo bases de datos": "데이터베이스 모드에 오신 것을 환영합니다",
  "Este es el modo bases de datos de Nodus: un gestor de tablas al estilo Notion, integrado en tu app. Te enseño en un minuto sus piezas con tres bases de datos de ejemplo ya cargadas. Puedes salir cuando quieras y volver a ver el tutorial desde Ajustes.": "이것은 Nodus의 데이터베이스 모드입니다. 앱에 내장된 Notion 스타일 테이블 관리자입니다. 잠시 후에 이미 로드된 세 가지 샘플 데이터베이스를 사용하여 해당 부분을 안내하겠습니다. 언제든지 나가서 설정에서 튜토리얼을 다시 재생할 수 있습니다.",
  "Tus bases de datos": "귀하의 데이터베이스",
  "En la barra lateral aparecen todas tus bases de datos. Cada una tiene un identificador único autogenerado. Pulsa una para abrirla, o el botón + para crear una nueva. Aquí abajo están también las secciones de Análisis y Chat.": "모든 데이터베이스가 사이드바에 나타납니다. 각각에는 자동 생성된 고유 ID가 있습니다. 하나를 클릭하여 열거나 + 버튼을 눌러 새 항목을 만듭니다. 분석 및 채팅 섹션은 다음과 같습니다.",
  "La tabla": "테이블",
  "Cada base de datos es una tabla de columnas tipadas: título, texto, número, fecha, hora, selección, selección múltiple y casilla. Arriba verás el número total de entradas y el porcentaje que suponen del total de todas tus bases de datos.": "각 데이터베이스는 제목, 텍스트, 번호, 날짜, 시간, 선택, 다중 선택 및 확인란 등 입력된 열의 테이블입니다. 상단에는 전체 항목 수와 모든 데이터베이스의 비율이 표시됩니다.",
  "Edita directamente": "제자리에서 편집",
  "Haz clic en cualquier celda para editarla al momento. Las columnas de selección muestran opciones con color que puedes añadir sobre la marcha; las casillas se marcan con un clic. Pasa el ratón por una fila para borrarla.": "즉시 편집하려면 아무 셀이나 클릭하세요. 선택 열에는 즉시 추가할 수 있는 색상으로 구분된 옵션이 표시됩니다. 클릭하면 확인란이 전환됩니다. 삭제하려면 행에 마우스를 올리세요.",
  "Columnas a tu medida": "원하는 대로 열을 구성하세요",
  "Pulsa la cabecera de una columna para renombrarla, cambiar su tipo o gestionar sus opciones, y usa el botón + del final de la cabecera para añadir nuevas columnas. Con «Nueva fila» añades registros.": "열 헤더를 클릭하여 이름을 바꾸고, 유형을 변경하거나, 옵션을 관리하고, 헤더 끝에 있는 +를 사용하여 새 열을 추가하세요. \"새 행\"은 레코드를 추가합니다.",
  "Análisis (próximamente)": "분석(곧 제공 예정)",
  "Aquí podrás elegir una base de datos y obtener estadísticas automáticas más un informe con IA, con gráficos y el cálculo a la vista para que sea reproducible. Llega en una próxima fase.": "여기에서 데이터베이스를 선택하고 자동 통계와 AI 보고서를 얻을 수 있으며, 차트와 계산이 표시되어 재현 가능하게 유지됩니다. 이후 단계에 도착합니다.",
  "Chat de datos (próximamente)": "데이터 채팅(제공 예정)",
  "Un chat adaptado para conversar con una o varias de tus bases de datos, capaz de generar gráficos y consultas reproducibles. También llega en una próxima fase.": "하나 이상의 데이터베이스와 대화하도록 맞춤화된 채팅으로 차트와 재현 가능한 쿼리를 생성할 수 있습니다. 또한 나중 단계에 도착합니다.",
  "Listo para tus datos": "데이터 준비",
  "Esto es una demostración con datos de ejemplo. Cuando quieras empezar con los tuyos, crea una base de datos desde la barra lateral y añade tus columnas. Pronto podrás además importar CSV y subir archivos en masa.": "샘플 데이터가 포함된 데모입니다. 자신만의 것으로 시작하고 싶다면 사이드바에서 데이터베이스를 생성하고 열을 추가하세요. 곧 CSV 및 대량 업로드 파일을 가져올 수도 있습니다.",
