  "Cada tarea conserva un modelo principal y un alternativo independiente. Los estilos personalizados pueden seguir fijando su propio modelo.": "각 작업은 독립적인 기본 및 대체 모델을 유지합니다. 사용자 정의 스타일은 여전히 ​​자체 모델을 지정할 수 있습니다.",
