  "No, ahora no": "아니요, 지금은 아닙니다.",
  "Nodus puede extraer conceptos, relaciones y citas textuales para crear el mapa de Ideas y el grafo de estudio.": "Nodus는 개념, 관계 및 축어적 인용문을 추출하여 아이디어 지도 및 연구 그래프를 만들 수 있습니다.",
  "El análisis se realizará en este dispositivo con el modelo seleccionado; el archivo no saldrá del equipo.": "분석은 선택한 모델을 사용하여 이 장치에서 실행됩니다. 파일은 이 컴퓨터를 떠나지 않습니다.",
  "Se enviarán al proveedor indicado el título y el texto extraído necesario. El archivo original permanecerá en tu dispositivo.": "제목과 필요한 추출 텍스트가 지정된 공급자에게 전송됩니다. 원본 파일은 장치에 남아 있습니다.",
