  "Controla si Nodus crea automáticamente conceptos, citas y relaciones para el mapa de Ideas y el grafo de estudio.": "Nodus가 아이디어 지도 및 연구 그래프에 대한 개념, 인용 및 관계를 자동으로 생성하는지 여부를 제어합니다.",
