  "Usar modelo de estudio/síntesis": "연구/합성 모델 사용",
  "Sin modelo alternativo": "대체 모델 없음",
  "Modelo del proveedor": "공급자 모델",
  "Heredar modelo principal": "기본 모델 상속",
  "Lleva tus notas, datos de estudio, materiales y grabaciones, borradores, búsquedas guardadas, auditorías de relaciones, bases de datos y Copias protegidas a otro equipo. Al importar se fusiona por fecha: gana la versión más reciente; las eliminaciones de Copias protegidas también se sincronizan mediante borrado lógico.": "메모, 학습 데이터, 자료 및 녹음, 초안, 저장된 검색, 관계 감사, 데이터베이스 및 보호 사본을 다른 컴퓨터로 가져가세요. 수입품은 날짜별로 병합됩니다. 최신 버전이 우선합니다. 보호된 복사본의 삭제도 일시 삭제를 통해 동기화됩니다.",
  "Esta acción elimina datos de forma permanente. ¿Quieres continuar?": "이 작업을 수행하면 데이터가 영구적으로 삭제됩니다. 계속하시겠습니까?",
  "Administración del vault de estudio": "연구실 관리",
  "Comprobaciones locales de SQLite, almacenamiento, índices, huérfanos y papelera.": "로컬 SQLite, 스토리지, 인덱스, 고아 및 휴지통 검사.",
