  "Paquete": "패키지",
  "Analíticas de estudio desactivadas": "연구 분석이 비활성화되었습니다.",
  "Puedes activarlas en Ajustes → Modelos IA. Los repasos siguen funcionando localmente.": "설정 → AI 모델에서 활성화할 수 있습니다. 리뷰는 계속해서 로컬에서 작동합니다.",
  "Modelos de IA": "AI 모델",
  "Un modelo general atiende conversación, análisis, resúmenes y las demás tareas de texto. Las capacidades especializadas se configuran debajo.": "하나의 일반 모델은 대화, 분석, 요약 및 기타 텍스트 작업을 처리합니다. 전문화된 기능은 아래와 같이 구성됩니다.",
  "El modelo general sigue siendo la base. Cada selector vacío hereda de él; los modelos de las herramientas se guardan solo en el vault actual.": "일반 모델은 기본으로 남아 있습니다. 모든 빈 선택자는 이를 상속받습니다. 도구 모델은 현재 Vault에만 저장됩니다.",
  "Cada tarea utiliza el modelo concreto seleccionado. Los modelos de las herramientas se guardan solo en el vault actual.": "각 작업은 선택한 모델을 사용합니다. 도구 모델은 현재 Vault에만 저장됩니다.",
  "Modelo general de texto": "일반 텍스트 모델",
  "Conversación, análisis, resúmenes y fallback de cualquier tarea sin modelo propio.": "자체 모델 없이 모든 작업에 대한 대화, 분석, 요약 및 대체.",
  "Conversación, análisis, resúmenes y demás tareas de texto.": "대화, 분석, 요약 및 기타 텍스트 작업.",
  "Este modelo consume la cuota de tu suscripción, no crédito de API. Un análisis completo del corpus puede agotar el límite semanal o mensual de tu plan.": "이 모델은 API 크레딧이 아닌 구독 할당량을 사용합니다. 전체 코퍼스 분석으로 인해 계획의 주간 또는 월간 한도가 소진될 수 있습니다.",
  "Este modelo local es de visión y no extrae ideas de forma fiable (tiende a divagar y no cerrar el JSON). Para extracción, elige Gemma 4 E2B u otro modelo mayor.": "이 로컬 모델은 비전 지향적이며 아이디어를 안정적으로 추출하지 않습니다(JSON을 닫지 않고 횡설수설하는 경향이 있음). 추출을 위해서는 Gemma 4 E2B 이상의 모델을 선택하세요.",
  "Estos pesos son los mismos que Nodus descarta entre sus modelos integrados: al extraer ideas divagan y no cierran el JSON. Puedes usarlos igualmente, pero para extracción conviene un modelo mayor.": "이는 Nodus가 내장 모델에서 제외하는 것과 동일한 가중치입니다. 즉, 아이디어를 추출할 때 횡설수설하고 JSON을 닫지 않습니다. 계속 사용할 수 있지만 추출은 더 큰 모델에서 더 잘 수행됩니다.",
  "El paso falló sin dejar un motivo. Reintenta; si vuelve a fallar, revisa el modelo en Ajustes → Modelos de IA.": "이유를 기록하지 않고 단계가 실패했습니다. 다시 시도해 보세요. 다시 실패하면 설정 → AI 모델에서 모델을 확인하세요.",
  "Todavía no hay ningún modelo entre los que elegir. Pulsa «Cargar modelos» para ver los de tus proveedores, o marca los que quieras como favoritos en Ajustes → Proveedores de IA y modelos.": "아직 선택할 수 있는 모델이 없습니다. “모델 로드”를 눌러 공급자가 제공하는 모델을 보거나 설정 → AI 공급자 및 모델에서 원하는 모델에 별표를 표시하세요.",
  "Sin respuesta de {list}. Revisa su clave o que el servidor local esté abierto.": "{list}에서 응답이 없습니다. 해당 키를 확인하거나 로컬 서버가 실행 중인지 확인하세요.",
  "solo visión": "비전만",
  "Este modelo no puede usarse para extracción de ideas.": "이 모델은 아이디어 추출에 사용할 수 없습니다.",
  "Uso mi plan gratuito de este proveedor": "이 제공업체의 무료 요금제를 사용합니다.",
  "Ajusta las peticiones a los límites del nivel gratuito (recorta la longitud de salida y espera si se alcanza el límite por minuto) para que el análisis no falle. Déjalo desmarcado si pagas por uso.": "분석이 실패하지 않도록 요청을 무료 계층 제한에 맞춰 조정합니다(출력 길이를 자르고 분당 제한에 도달하면 대기). 사용량에 따라 비용을 지불하는 경우 선택하지 않은 상태로 두세요.",
