  "Se eliminará «{model}» del almacenamiento de Nodus. Si está seleccionado, las funciones que lo usan dejarán de funcionar hasta que elijas otro modelo o vuelvas a descargarlo.": "\"{model}\"이(가) Nodus 저장소에서 제거됩니다. 이 모델을 선택하면 다른 모델을 선택하거나 다시 다운로드할 때까지 해당 모델을 사용하는 기능의 작동이 중지됩니다.",
  "Cambiar modelo de embeddings": "임베딩 모델 변경",
  "Los embeddings creados con el modelo anterior no son compatibles con el nuevo. Nodus conservará los datos, pero tendrás que reindexar para que la búsqueda semántica y las relaciones usen el nuevo modelo. ¿Cambiar de todos modos?": "이전 모델로 생성된 임베딩은 새 모델과 호환되지 않습니다. Nodus는 데이터를 유지하지만 의미 검색 및 관계가 새 모델을 사용하려면 먼저 다시 색인을 생성해야 합니다. 그래도 바꾸시겠어요?",
  "Cambiar modelo": "모델 변경",
  "Si cambias de modelo de embeddings, los vectores anteriores no servirán con el nuevo modelo y tendrás que reindexar.": "임베딩 모델을 변경하면 기존 벡터가 새 모델에서 작동하지 않으므로 다시 색인을 생성해야 합니다.",
  "Embeddings multilingües de alta calidad para corpus amplios.": "대규모 말뭉치를 위한 고품질 다국어 임베딩입니다.",
  "Embeddings multilingües con contexto largo y buen equilibrio entre precisión y memoria.": "정확성과 메모리 사용의 균형이 잘 잡힌 긴 상황의 다국어 임베딩입니다.",
  "Opción ligera y rápida para equipos con menos memoria.": "메모리가 적은 컴퓨터를 위한 가볍고 빠른 옵션입니다.",
  "Modelo visual muy ligero para conversación, resúmenes e ideas.": "대화, 요약 및 아이디어를 위한 매우 가벼운 비전 모델입니다.",
  "Modelo visual de mayor calidad; requiere más almacenamiento y memoria.": "더 많은 저장 공간과 메모리가 필요한 고품질 비전 모델입니다.",
  "Modelo visual compacto orientado a documentos e imágenes.": "문서 및 이미지용으로 설계된 컴팩트 비전 모델입니다.",
