  "Por ejemplo, 1º ESO A": "예를 들어, 7A년차",
  "Se copiarán los nombres y apellidos al final de este listado. Es una copia: editar un grupo no cambia el otro.": "이름과 성은 이 목록의 끝에 복사됩니다. 이는 복사본입니다. 한 그룹을 편집해도 다른 그룹은 변경되지 않습니다.",
  "Se crearán esas filas vacías para que rellenes el listado. Podrás añadir o quitar después.": "입력할 빈 행이 많이 생성됩니다. 나중에 더 추가하거나 제거할 수 있습니다.",
  "Se eliminará este grupo y su listado de alumnado. Esta acción no se puede deshacer.": "이 그룹과 해당 수업 목록이 삭제됩니다. 이 작업은 취소할 수 없습니다.",
  "Se sustituyen por identificadores. No cubre transcripción de audio, análisis de imágenes ni embeddings.": "식별자로 대체됩니다. 오디오 전사, 이미지 분석 또는 임베딩은 다루지 않습니다.",
