  "Ningún personaje coincide con el filtro.": "필터와 일치하는 문자가 없습니다.",
  "Quitar los filtros": "필터 지우기",
  "Todavía no hay personajes en este mundo.": "이 세계에는 아직 캐릭터가 없습니다.",
  "Especie": "종",
  "Género": "성별",
