  "Cómo la vive": "그들이 어떻게 느끼는지",
  "Solo desde su lado: la otra persona puede vivir la misma relación de forma muy distinta.": "자신의 입장에서만: 상대방은 동일한 유대관계를 매우 다르게 살아갈 수 있습니다.",
