  "Muere el año {death}, antes de nacer el año {birth}.": "{birth}년에 태어나기 전 {death}년에 사망합니다.",
  "Participa en un hecho el año {year}, después de morir el año {death}.": "{death}에 사망한 후 {year}년에 이벤트에 참여합니다.",
  "Participa en un hecho el año {year}, antes de nacer el año {birth}.": "{birth}에 태어나기 전인 {year}년에 이벤트에 참여합니다.",
  "Tiene fecha de muerte pero su estado sigue siendo «vivo».": "사망 날짜가 있지만 여전히 '살아 있음'으로 표시되어 있습니다.",
  "Está marcado como muerto pero no consta cuándo.": "죽은 것으로 표시되어 있지만 언제인지 기록은 없습니다.",
  "El nombre se parece mucho a «{other}»: quien lea puede confundirlos.": "이름은 \"{other}\"에 매우 가깝습니다. 독자가 혼동할 수 있습니다.",
  "Proponer": "제안하다",
  "Proponiendo…": "제안…",
  "Propuesta sin aceptar": "수락되지 않은 제안",
  "Aceptar como canon": "정식으로 받아들인다",
  "Lo que va entre corchetes lo ha inventado la IA. No es canon hasta que lo aceptes.": "괄호 안의 내용은 AI가 발명한 것입니다. 당신이 그것을 받아들이기 전까지는 그것은 정경이 아닙니다.",
  "Solo cuenta lo que ya está en la ficha": "이미 시트에 있는 내용만 알려줍니다.",
  "Rellena los huecos y marca entre corchetes lo que ha inventado": "무엇이든 간에 간격과 괄호를 채웁니다.",
  "Entrevistar": "회견",
  "Entrevistar a {name}": "인터뷰 {name}",
  "Hablar con el personaje en su propia voz": "자신의 목소리로 캐릭터와 대화",
  "Responde en su voz y solo sabe lo que hay en su ficha. Nada de esta conversación se guarda.": "그들은 자신의 목소리로 대답하고 자신의 시트에 있는 내용만 알고 있습니다. 이 대화는 저장되지 않습니다.",
  "Responde en su propia voz; las conversaciones se guardan en esta bóveda.": "그들은 자신들의 목소리로 대답합니다. 대화는 이 저장소에 저장됩니다.",
  "Se eliminará «{title}» junto con todos sus mensajes e imágenes. Esta acción no se puede deshacer.": "“{title}”은 모든 메시지 및 이미지와 함께 삭제됩니다. 이 작업은 취소할 수 없습니다.",
  "Pregúntale algo.": "그들에게 뭔가 물어보세요.",
  "Rellena antes su descripción: sin ficha no tiene nada que contestar.": "먼저 설명을 작성하세요. 시트가 없으면 답변할 내용이 없습니다.",
  "Tu pregunta…": "귀하의 질문은…",
  "Preguntar": "묻다",
  "«¿De qué te arrepientes?»": "“무엇을 후회하나요?”",
  "«¿A quién no soportas y por qué?»": "“누가 참지 못합니까, 왜요?”",
  "«¿Qué harías si te quitaran lo que más quieres?»": "“당신이 가장 사랑하는 것을 그들이 가져간다면 당신은 어떻게 하시겠습니까?”",
  "Exportar la ficha a Markdown": "시트를 Markdown으로 내보내기",
  "Ficha guardada en {path}": "{path}에 시트가 저장되었습니다.",
  "(sin los nombres secretos ni tus notas privadas)": "(비밀 이름이나 개인 메모 제외)",
  "Plantilla": "주형",
  "Solo el nombre. Rellena la ficha a tu manera.": "이름만요. 자신만의 방식으로 시트를 채워보세요.",
  "Héroe a su pesar": "꺼리는 영웅",
  "Alguien a quien la trama saca de su vida sin pedirle permiso. Empieza por qué quería en realidad y qué le impide moverse.": "줄거리가 묻지 않고 삶에서 빠져 나가는 사람. 그들이 실제로 원했던 것과 그들을 계속 유지하는 것부터 시작하십시오.",
  "Tirano con razones": "이유가 있는 폭군",
  "Un antagonista que cree estar salvando algo. Lo importante es la mentira que se cree y de dónde salió.": "자신이 무언가를 구하고 있다고 믿는 적대자. 중요한 것은 그들이 믿는 거짓말과 그것이 어디서 왔는지입니다.",
  "Mentor con secreto": "비밀이 있는 멘토",
  "Quien enseña y calla lo que más importa. Define qué protege ocultándolo.": "가장 중요한 것을 가르치고 보류하는 사람. 무엇을 숨겨서 보호하는지 정의하세요.",
  "Embaucador": "사기꾼",
  "Quien sobrevive hablando y cambia de bando a tiempo. Su voz es media ficha.": "말로 살아남고, 시간의 흐름에 따라 입장을 바꾸는 사람. 그들의 목소리는 시트의 절반입니다.",
  "Testigo": "증인",
  "Un personaje menor que ve lo que nadie más ve. Con poco basta: qué vio y por qué calla.": "아무도 보지 않는 것을 보는 작은 캐릭터. 조금만 있으면 충분합니다. 그들이 본 것과 침묵하는 이유.",
  "Familias": "가족",
  "Dinastías": "왕조",
  "Calendario del mundo": "세계 달력",
  "Definir las eras y los meses de tu mundo": "세계의 시대와 달을 정의하세요",
  "Opcional. Sin calendario, el año ordena la cronología igual que hasta ahora; con él, además ordena dentro de cada año y puedes elegir la fecha en vez de escribirla.": "선택 과목. 달력이 없으면 연도는 이전과 똑같이 타임라인을 정렬합니다. 하나는 매년 주문하고, 날짜를 입력하는 대신 날짜를 선택하는 것입니다.",
  "Nombre del calendario (opcional)": "캘린더 이름(선택사항)",
  "Guardar calendario": "달력 저장",
  "Al guardar se recalculan las fechas de todos los hechos ya registrados.": "저장하면 이미 기록된 모든 이벤트의 날짜가 다시 계산됩니다.",
