  "Año inicial": "시작 연도",
  "El «año inicial» es el año absoluto en el que cae el año 1 de esa era: es lo que permite comparar fechas de eras distintas.": "\"시작 연도\"는 시대의 1년이 속하는 절대 연도입니다. 이를 통해 여러 시대의 날짜를 비교할 수 있습니다.",
