  "Qué ha pasado aquí antes del relato.": "이야기가 시작되기 전에 무슨 일이 일어났나요?",
  "Arquitectura, materiales, colores, cómo se llega…": "건축, 재료, 색상, 도착 방법…",
  "Ruidos, olores, quién anda por la calle, qué se teme…": "소리, 냄새, 거리에 누가 있는지, 무엇이 두려운지…",
  "Fundación, guerras, quién lo gobernó…": "건국, 전쟁, 그것을 지배한 사람…",
  "Lo que se añade a todas las imágenes para que el lugar se parezca a sí mismo.": "장소가 그 자체처럼 보이도록 모든 이미지에 추가되었습니다.",
  "p. ej. «ciudad portuaria de piedra gris, tejados de pizarra, niebla»": "예를 들어 “회색 돌 항구 도시, 슬레이트 지붕, 안개”",
  "Quién está aquí": "여기 누구야?",
  "Nadie por ahora. Se añaden desde la ficha del personaje, en sus lugares.": "아직 아무도 없습니다. 캐릭터 시트에서 해당 위치에 추가됩니다.",
  "Un lugar de tipo «{child}» está dentro de uno de tipo «{parent}». ¿Es a propósito?": "“{child}”은 “{parent}” 안에 있습니다. 의도적인 걸까요?",
  "¿Eliminar este lugar? Los lugares que contiene NO se borran: pasan a estar sueltos.": "이 장소를 삭제하시겠습니까? 그 안의 장소는 삭제되지 않고 배치되지 않습니다.",
  "¿Eliminar esta imagen de la galería?": "갤러리에서 이 이미지를 삭제하시겠습니까?",
  "Escribe primero la apariencia en la sección Descripción.": "설명 섹션에 모양을 먼저 작성하세요.",
