  "Crea antes una facción, una cultura o una dinastía.": "먼저 세력, 문화, 왕조를 만드세요.",
  "Nadie por ahora. Se añaden desde la ficha del personaje, en sus pertenencias.": "아직 아무도 없습니다. 캐릭터 시트의 멤버십 아래에 추가됩니다.",
  "En una línea": "한 줄에",
  "Lo que dirías de esto en una frase.": "한 문장으로 그것에 대해 무엇을 말하시겠습니까?",
  "Lo que se ve: emblemas, colores, vestimenta, arquitectura.": "눈에 보이는 것: 상징, 색상, 드레스, 건축물.",
  "Símbolos, atuendo, cómo se reconoce a los suyos…": "상징, 복장, 자신의 것이 어떻게 인식되는지…",
  "Lo que se añade a todas las imágenes para que se parezcan entre sí.": "모든 이미지에 추가되어 유사해 보입니다.",
  "p. ej. «heráldica de cuervo negro sobre campo gris, plata bruñida»": "예를 들어 \"회색 들판 위의 검은 까마귀 문장, 빛나는 은색\"",
  "p. ej. «los espías de la corte, que ya no responden ante nadie»": "예를 들어 “더 이상 아무에게도 대답하지 않는 법원의 스파이들”",
  "{from} → {to}": "{from} → {to}",
  "¿Eliminar esto? Los personajes NO se borran: solo dejan de pertenecer.": "이것을 삭제하시겠습니까? 캐릭터는 삭제되지 않으며 단순히 소속이 중단됩니다.",
