  "Sube": "상승",
  "Aquí aparecerán los conflictos y arcos de quienes salen en la escena. Crea uno y esta escena empezará a contar para él.": "이 장면에 등장하는 인물의 갈등과 호불호가 여기에 표시됩니다. 하나를 만들면 이 장면이 계산되기 시작합니다.",
  "Esta escena todavía no mueve nada.": "이 장면은 아직 아무것도 움직이지 않습니다.",
  "Nada todavía": "아직 아무것도 없습니다",
  "Quién quiere qué contra quién": "누가 누구를 상대로 무엇을 원하는가",
  "Qué cambia, en una frase": "어떤 변화를, 한 문장으로",
  "Qué cambia, y en quién": "무엇이 바뀌고, 누구에게 바뀌나요?",
  "Qué se mueve aquí": "여기로 움직이는 것은 무엇입니까?",
  "{count} de {total}": "{total} 중 {count}",
  "Actúa antes de nacer": "태어나기 전에 행동한다",
  "Actúa después de morir": "죽은 뒤에 행동한다",
  "Alguien aparece antes de la fecha de su nacimiento.": "누군가가 생년월일보다 먼저 나타납니다.",
  "Alguien aparece en una escena o un hecho posterior a su muerte.": "누군가가 죽은 후의 장면이나 사건에 등장합니다.",
  "Alguien conoce un secreto antes que quien lo guardaba.": "누군가는 그것을 간직한 사람보다 먼저 비밀을 알고 있습니다.",
  "Alguien está en dos lugares distintos el mismo día del mundo.": "누군가가 같은 세계일에 서로 다른 두 장소에 있습니다.",
  "El tiempo entre dos lugares no da para llegar, según los modos de viaje del mundo.": "전 세계의 여행 방식을 고려할 때 두 장소 사이에 충분한 시간이 없습니다.",
  "En dos sitios a la vez": "동시에 두 곳에서",
  "En {sources}": "{sources}에서",
  "Escenas sin día": "낮이 없는 장면",
  "La fecha de muerte, el estado vital y los hechos de la ficha no encajan entre sí.": "사망 날짜, 생활 상태 및 시트의 사건이 서로 맞지 않습니다.",
  "La ficha se contradice": "시트 자체가 모순됩니다",
  "La jerarquía de lugares se cierra en un bucle.": "장소의 계층 구조는 루프로 닫힙니다.",
  "La pertenencia acaba antes de empezar.": "멤버십은 시작되기 전에 종료됩니다.",
  "Lo sabe antes que nadie": "누구보다 먼저 알아요",
  "Nadie pudo contarle «{secret}» a {person}": "누구도 {person}에게 “{secret}”에 대해 말할 수 없었을 것입니다.",
  "Nadie pudo contárselo": "아무도 그들에게 말할 수 없었을 거예요",
  "No hay ninguna escena ni hecho donde coincidiera con alguien que ya lo supiera.": "이미 아는 사람과 함께 있는 장면이나 사건은 없습니다.",
  "Pertenencia al revés": "멤버십 역방향",
  "Quien lo sabe no coincidió nunca con alguien que ya lo supiera.": "그것을 아는 사람은 이미 그런 사람과 길을 건너지 않았습니다.",
  "Sin día del mundo, las comprobaciones de presencia, viajes y secretos no pueden hablar de ellas.": "세계의 날이 없으면 존재, 여행 및 비밀 수표가 그들에 대해 아무 말도 할 수 없습니다.",
  "Sin día, las comprobaciones de presencia, viajes y secretos no pueden decir nada sobre ellas.": "하루가 없으면 존재, 여행 및 비밀 수표가 그들에 대해 아무 말도 할 수 없습니다.",
  "Un lugar dentro de sí mismo": "그 자체의 장소",
  "Viaje imposible": "불가능한 여행",
  "{count} escenas no tienen día del mundo": "{count} 장면에는 세계의 날이 없습니다.",
  "{person} deja {group} antes de entrar": "{person}이(가) 합류하기 전에 {group}을(를) 떠납니다.",
  "{person} está a la vez en {a} y en {b}": "{person}은(는) {a}과 {b}에 동시에 있습니다.",
  "{person} sabe «{secret}» antes que quien lo guardaba": "{person}은(는) 그것을 보관한 사람보다 먼저 “{secret}”을 알고 있습니다.",
  "{person} va de {from} a {to} en menos tiempo del que se tarda": "{person}은 걸리는 시간보다 더 짧은 시간에 {from}에서 {to}까지 이동합니다.",
  "{place} acaba conteniéndose a sí mismo": "{place}은(는) 결국 자신을 포함하게 됩니다.",
  "Es a propósito": "그것은 고의로",
  "Presencia": "있음",
  "Se lo contaron": "그들은 들었다",
  "Tiene un doble": "그들은 두 배를 가지고 있습니다",
  "Todavía no lo sé": "나는 아직 모른다",
  "Viajes": "여행",
