  "Certeza": "확실성",
  "Dejaré de avisarte de esto. Puedes verlo y deshacerlo en «Excepciones aceptadas».": "나는 이것에 대해 당신에게 말하지 않을 것입니다. “허용된 예외”에서 이를 확인하고 실행 취소할 수 있습니다.",
  "Está bien así": "이대로도 괜찮아",
