  "Falta información": "적어두기가 부족해요",
  "Habría que mirarlo": "볼만한 가치가 있는",
  "He comprobado {checks} cosas de {families} familias sobre {facts} hechos.": "{facts}개의 사실보다 {families}가족의 {checks}개 항목을 확인했습니다.",
  "Implica a": "포함",
