  "No puedes escribir «{scene}» sin decidirlo (escena {order} del relato).": "결정하지 않고는 “{scene}”이라고 쓸 수 없습니다(이야기의 장면 {order}).",
  "No puedo seguir sin esto": "이것 없이는 계속할 수 없어",
