  "Se borra con sus opciones. Si venía de un hueco en tu prosa, volverá a aparecer.": "해당 옵션과 함께 삭제됩니다. 그것이 산문의 구멍에서 나왔다면 다시 돌아올 것입니다.",
  "Se creará el artículo «{title}»": "“{title}” 기사가 생성됩니다.",
