  "¿Borrar los datos seleccionados?": "선택한 데이터를 삭제하시겠습니까?",
  "¿Borrar todos los datos de navegación?": "인터넷 사용 기록을 모두 삭제하시겠습니까?",
  "Borrar las cookies cerrará tu sesión en los sitios donde la tengas iniciada.": "쿠키를 삭제하면 로그인되어 있는 사이트에서 로그아웃됩니다.",
  "También se cerrarán todas las pestañas abiertas del navegador.": "열려 있는 브라우저 탭도 모두 닫힙니다.",
  "Chromium borra las cookies por dominio registrable: al borrar las de un subdominio se borran también las del dominio principal y sus demás subdominios.": "Chromium은 등록 가능한 도메인별로 쿠키를 삭제합니다. 하위 도메인의 쿠키를 삭제하면 기본 도메인과 다른 하위 도메인의 쿠키도 삭제됩니다.",
  "Nodus puede medir la caché y el tamaño total del perfil. Chromium no informa del tamaño de cada categoría de almacenamiento por separado, así que las demás se muestran por número de sitios afectados.": "Nodus는 캐시와 전체 프로필 크기를 측정할 수 있습니다. Chromium은 각 저장소 범주의 크기를 별도로 보고하지 않으므로 나머지는 영향을 받는 사이트 수로 표시됩니다.",
  "Nodus Browser conserva cookies y almacenamiento de sitio para que sigas con la sesión iniciada donde corresponda. Nodus no guarda usuarios ni contraseñas, y no incluye gestor de contraseñas.": "Nodus Browser는 쿠키와 사이트 저장 공간을 유지하므로 적절한 경우 로그인 상태를 유지할 수 있습니다. Nodus는 사용자 이름과 비밀번호를 저장하지 않으며 비밀번호 관리자도 포함하지 않습니다.",
  "IndexedDB": "IndexedDB",
