  "Se han guardado {n} archivo(s).": "{n}개의 파일이 저장되었습니다.",
  "Copias previas a migraciones": "마이그레이션 전 사본",
  "Antes de cambiar el esquema, Nodus conserva una copia inmutable y verificada. Puedes abrirla como un vault separado sin sustituir el actual.": "Nodus는 스키마를 변경하기 전에 불변의 확인된 복사본을 유지합니다. 현재 Vault를 바꾸지 않고도 별도의 Vault로 열 수 있습니다.",
  "La copia previa se abrió como un vault separado.": "마이그레이션 전 복사본은 별도의 저장소로 열렸습니다.",
  "Abriendo…": "열기…",
