  "Coordina la edición del volumen; las ideas no se le atribuyen.": "볼륨을 편집합니다. 그 아이디어는 그들에게 귀속되지 않습니다.",
  "Excepción: los marcados no registran ningún autor, así que sus ideas se muestran aquí de forma provisional.": "예외: 표시된 것들은 저자가 전혀 기록되어 있지 않으므로 그들의 아이디어가 여기에 임시로 표시됩니다.",
  "Esta obra no registra ningún autor: sus ideas se atribuyen provisionalmente a quien la edita": "이 작품에는 저자가 기록되어 있지 않습니다. 해당 작품의 아이디어는 잠정적으로 편집한 사람에게 귀속됩니다.",
  "atribución provisional": "잠정귀속",
  "provisional": "임시",
  "Reparando": "수리 중",
  "Publicando": "출판",
  "El texto disponible ha cambiado. Se conserva el análisis anterior hasta completar un reescaneo.": "사용 가능한 텍스트가 변경되었습니다. 이전 분석은 재검색이 완료될 때까지 유지됩니다.",
  "El adjunto existe en Zotero, pero el archivo ya no está en su ubicación original.": "첨부 파일은 Zotero에 존재하지만 파일은 더 이상 원래 위치에 없습니다.",
  "El PDF está escaneado y no tiene capa de texto. Activa OCR y vuelve a analizar.": "PDF가 스캔되었으며 텍스트 레이어가 없습니다. OCR을 활성화하고 다시 분석해 보세요.",
  "El adjunto no produjo texto utilizable. Revisa el archivo o activa OCR.": "첨부 파일에서 사용할 수 있는 텍스트가 생성되지 않았습니다. 파일을 확인하거나 OCR을 활성화하십시오.",
  "El formato del adjunto no es compatible con la extracción de texto.": "텍스트 추출에는 첨부 형식이 지원되지 않습니다.",
  "Selecciona al menos una referencia.": "참조를 하나 이상 선택하세요.",
  "{n} referencias": "{n} 참조",
