  "XPI verificado guardado en:": "확인된 XPI가 다음 위치에 저장되었습니다.",
  "En Zotero: Herramientas → Complementos → ⚙ → Instalar complemento desde archivo.": "Zotero에서: 도구 → 플러그인 → ⚙ → 파일에서 애드온 설치.",
  "Guardar .xpi para Zotero": "Zotero용.xpi 저장",
