  "Publicar fuentes primarias revisadas": "검토된 기본 소스 게시",
  "Incluye metadatos, extractos y análisis; nunca archivos originales, rutas locales ni datos privados.": "메타데이터, 발췌 및 분석이 포함됩니다. 원본 파일, 로컬 경로 또는 개인 데이터는 절대 사용하지 마세요.",
  "Publicar testimonios textuales": "텍스트 증언을 게시",
  "Incluye entrevistas, transcripciones y análisis; participantes, acuerdos y archivos multimedia permanecen privados.": "인터뷰, 성적표, 분석이 포함됩니다. 참가자, 계약 및 미디어 파일은 비공개로 유지됩니다.",
  "Espacio de trabajo": "작업공간",
  "notas, borradores y organización": "메모, 초안 및 구성",
  "Organiza notas, borradores y materiales en un único espacio con citas verificables.": "검증 가능한 인용을 통해 메모, 초안, 자료를 한 공간에 정리하세요.",
  "Organiza el trabajo del corpus": "말뭉치 작업 정리",
  "Ya hay suficientes ideas y fuentes para organizar notas y borradores con citas verificables en un único espacio de trabajo.": "하나의 작업 공간에는 검증 가능한 인용이 포함된 메모와 초안을 정리할 수 있는 충분한 아이디어와 소스가 있습니다.",
  "Abrir espacio de trabajo": "작업공간 열기",
  "Espacio de trabajo: notas y borradores con fuentes verificables": "작업 공간: 검증 가능한 소스가 포함된 메모 및 초안",
  "El Espacio de trabajo reúne notas, borradores y organización en una única superficie. Conserva las citas clicables y permite estructurar el manuscrito sin separar artificialmente Escritura y Proyectos.": "작업 공간은 메모, 초안 및 구성을 한 화면에 함께 제공합니다. 인용을 클릭 가능하게 유지하고 글쓰기와 프로젝트를 인위적으로 분리하지 않고도 원고를 구조화할 수 있습니다.",
  "Revisa, amplía y transforma borradores en el Espacio de trabajo.": "작업공간에서 초안을 검토, 확장 및 변환합니다.",
  "Leyendo colecciones…": "컬렉션을 읽는 중…",
  "Catalogando…": "목록 작성 중…",
  "Leyendo notas…": "메모를 읽는 중…",
  "Copiando archivos…": "파일 복사 중…",
  "Verificando el índice local…": "로컬 색인 확인 중…",
  "Importación completada": "가져오기 완료",
  "Importación cancelada": "가져오기가 취소되었습니다.",
  "No se pudo completar la importación": "가져오기를 완료할 수 없습니다.",
  "Cancelar importación": "가져오기 취소",
  "Ocultar la importación terminada": "완료된 가져오기 숨기기",
  "Importar archivos sueltos (sin ficha bibliográfica)": "독립형 파일 가져오기(서지 항목 없음)",
  "PDFs y EPUBs añadidos a Zotero sin una entrada encima. Llegan sin autor ni año.": "PDF 및 EPUB가 위에 항목 없이 Zotero에 추가되었습니다. 저자나 연도 없이 도착합니다.",
  "Archivos sueltos no importados": "가져오지 않은 독립 실행형 파일",
  "Tu biblioteca tiene {n} archivo(s) sin ficha bibliográfica. Marca la casilla de arriba y vuelve a importar si los quieres.": "귀하의 도서관에는 참고문헌 항목이 없는 {n}개의 파일이 있습니다. 원하는 경우 위의 확인란을 선택하고 다시 가져오세요.",
  "La app ha alcanzado su límite de almacenamiento (256 KB).": "앱이 저장 용량 한도(256KB)에 도달했습니다.",
  "El almacenamiento no está activado.": "저장소가 활성화되지 않았습니다.",
  "La clave o el dato no son válidos.": "키 또는 데이터가 유효하지 않습니다.",
  "Conversación no encontrada.": "대화를 찾을 수 없습니다.",
  "Informe sin título": "제목 없는 보고서",
  "(tu servidor)": "(귀하의 서버)",
  "Conecta Nodus con cualquier servidor que hable la API de OpenAI: LiteLLM, vLLM, el servidor de llama.cpp o un proxy propio.": "OpenAI API를 사용하는 모든 서버(LiteLLM, vLLM, llama.cpp 서버 또는 자체 프록시)에 Nodus를 연결하세요.",
  "Dirección del servidor (URL completa)": "서버 주소(전체 URL)",
  "Nodus no añade \"/v1\" por su cuenta: escribe la ruta exacta que sirve tu servidor.": "Nodus는 \"/v1\"을 자체적으로 추가하지 않습니다. 서버가 제공하는 정확한 경로를 입력하세요.",
  "•••••••• clave guardada (opcional)": "•••••••• 키 저장됨(선택 사항)",
  "clave de API (opcional)": "API 키(선택사항)",
  "Modelos escritos a mano": "손으로 입력하는 모델",
  "Si tu servidor no publica catálogo, escribe aquí los identificadores. Quedan guardados y se pueden elegir en cualquier selector de modelo.": "서버에서 카탈로그를 게시하지 않는 경우 여기에 식별자를 입력하세요. 이는 저장되며 모든 모델 선택기에서 선택할 수 있습니다.",
  "identificador del modelo": "모델 식별자",
  "Quitar modelo": "모델 삭제",
  "Ni el servidor publica modelos ni has escrito ninguno todavía.": "서버는 모델을 게시하지 않으며 아직 입력하지 않았습니다.",
  "Este proveedor genera texto, no embeddings. Para la búsqueda semántica elige otro proveedor en Ajustes.": "이 공급자는 임베딩이 아닌 텍스트를 생성합니다. 의미 검색의 경우 설정에서 다른 공급자를 선택하세요.",
  "Instalar y reiniciar": "설치 및 다시 시작",
  "Más tarde": "나중에",
  "Actualización {version} lista. Puedes instalarla y reiniciar cuando quieras.": "{version} 업데이트가 준비되었습니다. 원할 때마다 설치하고 다시 시작할 수 있습니다.",
  "Puedes seguir trabajando. Nodus solo se reiniciará cuando elijas instalar la actualización.": "계속 일할 수 있습니다. Nodus는 업데이트 설치를 선택한 경우에만 다시 시작됩니다.",
  "No se pudo instalar la actualización. Puedes volver a intentarlo.": "업데이트를 설치할 수 없습니다. 다시 시도해 보세요.",
  "La actualización anterior no llegó a instalarse. Busca actualizaciones para volver a intentarlo.": "이전 업데이트가 설치되지 않았습니다. 다시 시도하려면 업데이트를 확인하세요.",
  "No se pudo descargar la actualización. Comprueba tu conexión y vuelve a intentarlo.": "업데이트를 다운로드할 수 없습니다. 연결을 확인하고 다시 시도하세요.",
  "CARTOGRAFÍA DEL ARGUMENTO": "인수 지도 제작",
  "Todas las ramas": "전 지점",
